window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch02"]={"id": "ch02", "title": "第二章 细胞质膜及跨膜运输", "sub": "翟中和《细胞生物学》第4版 · 教师课件逐页详解", "sub2": "膜结构 · 流动性 · 被动/主动运输", "modules": [{"i": 0, "name": "模块一：生物膜结构模型与组成", "slides": [{"i": 0, "sec": "第一节 膜的组成", "title": "细胞质膜与跨膜运输·开篇 (p1)", "notes": "由膜脂、蛋白质、糖类组成，与细胞基本的生命活动密切相关。进化上：质膜的形成是非细胞生命(病毒)与细胞生物的重要分界点；细胞内膜系统的发展是细胞生物由低等到高等发展的反映。生物膜=质膜+细胞内膜系统。", "page": 1, "level": "掌握", "img": "assets/img/ch02/p001.jpg", "anim": null, "fig": null, "points": null}, {"i": 1, "sec": "第一节 膜的组成", "title": "膜的基本功能 (p2)", "notes": "①屏障、半透膜，维护细胞内微环境的相对稳定；②细胞与外界进行物质、能量、信息交换。膜是细胞与外界环境的边界与交流界面。", "page": 2, "level": "掌握", "img": "assets/img/ch02/p002.jpg", "anim": null, "fig": null, "points": ["质膜的基本功能：①界定细胞、维持内环境稳定；②控制物质进出(选择透过性)；③信息传递(受体)；④细胞识别(糖链)；⑤连接与支撑。"]}, {"i": 2, "sec": "第一节 膜的组成", "title": "流动镶嵌模型 (p3)", "notes": "流动镶嵌模型(1972 Singer & Nicolson)：①具有极性头部和非极性尾部的磷脂双分子层是生物膜的基本结构组分；②不同膜蛋白与膜脂双分子层亲和性不同、作用方式不同、位置不同；③脂类和蛋白质的流动性与不对称性是相互作用的基础；④这种相互作用又一定程度限制了膜蛋白和膜脂的流动性。", "page": 3, "level": "掌握", "img": "assets/img/ch02/p003.jpg", "anim": "fluid_mosaic", "fig": null, "points": null}, {"i": 3, "sec": "第一节 膜的组成", "title": "三明治模型与流体镶嵌模型 (p4)", "notes": "三明治模型(蛋白质分布描述有差异)→流体镶嵌模型。流体镶嵌模型要点：①不同蛋白质镶嵌于脂双层的方式不同——不对称性；②膜具流动性(蛋白质、脂类)。", "page": 4, "level": "理解", "img": "assets/img/ch02/p004.jpg", "anim": "fluid_mosaic_models", "fig": "膜结构模型的历史：1935 年 Davson-Danielli“三明治”模型(脂双层两侧铺蛋白) → 1972 年 Singer-Nicolson 流动镶嵌模型(蛋白镶嵌在流动的脂双层中)。图对比两模型，突出“膜是流动的、蛋白是镶嵌的”。", "points": null}, {"i": 4, "sec": "第一节 膜的组成", "title": "脂筏模型 (p6)", "notes": "细胞膜脂筏模型(Lipid raft model,1988)：在甘油磷脂为主体的膜上，胆固醇、鞘磷脂等富集区域形成相对独立的'脂筏'，其上承载执行特定生物功能的某些膜蛋白。①非离子去垢剂(如Triton X-100)可将脂筏从质膜分离，蛋白质组学分析含250多种蛋白；②脂筏是异质性、高度动态、分子排列较紧密的膜脂微区域；③参与细胞信息传递、物质运输等。", "page": 6, "level": "掌握", "img": "assets/img/ch02/p006.jpg", "anim": "lipid_raft", "fig": "脂筏(lipid raft)：膜上富含胆固醇和鞘脂的微区，比周围膜更有序、更厚，聚集特定蛋白(如 GPI 锚定蛋白、信号分子)。图显示脂筏是“漂浮”在流动性膜中的有序平台，参与信号转导和物质运输。", "points": null}, {"i": 5, "sec": "第一节 膜的组成", "title": "膜的组成组分 (p7)", "notes": "二、膜的组成组分。①膜脂——磷脂(甘油磷脂>50%，膜脂基本成分)、鞘磷脂；②糖脂/糖蛋白——短的寡糖通过共价键与膜脂或膜蛋白相连；③膜蛋白。", "page": 7, "level": "掌握", "img": "assets/img/ch02/p007.jpg", "anim": null, "fig": null, "points": null}, {"i": 6, "sec": "第一节 膜的组成", "title": "三种膜脂分子 (p8)", "notes": "三种膜脂分子：A甘油磷脂、B鞘磷脂和糖脂、C胆固醇。都是两性分子——同时具有亲水和疏水两种性质。这是形成脂双层的基础。", "page": 8, "level": "掌握", "img": "assets/img/ch02/p008.jpg", "anim": null, "fig": "膜脂主要有三种：①甘油磷脂(磷脂酰胆碱等，占 50% 以上，构成脂双层骨架)；②鞘脂(鞘磷脂、糖脂)；③胆固醇(调节流动性)。图对比三种脂质的结构与分布。", "points": null}, {"i": 7, "sec": "第一节 膜的组成", "title": "甘油磷脂 (p9)", "notes": "甘油磷脂：磷脂酰胆碱(卵磷脂)、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇。为膜脂基本成分，占整个膜脂50%以上。具有一个极性头和两条疏水尾。", "page": 9, "level": "掌握", "img": "assets/img/ch02/p009.jpg", "anim": null, "fig": null, "points": null}, {"i": 8, "sec": "第一节 膜的组成", "title": "鞘脂 (p10)", "notes": "鞘脂：鞘氨醇的衍生物，主要在高尔基体合成，分鞘磷脂、鞘糖脂两类。具极性头部基团(亲水)和非极性尾部基团(疏水)。鞘磷脂不以甘油为骨架，而以鞘氨醇为骨架。", "page": 10, "level": "掌握", "img": "assets/img/ch02/p010.jpg", "anim": null, "fig": null, "points": null}, {"i": 9, "sec": "第一节 膜的组成", "title": "胆固醇 (p11)", "notes": "胆固醇：含4个闭环的碳氢化合物，亲水头部为一个羟基。①自身不能形成脂双层，只能插入磷脂分子之间参与生物膜形成；②调节膜的流动性，增加膜稳定性及降低水溶性物质通透性；③脂筏基本结构成分，很多重要生物活性分子的前体；④动物细胞质膜含胆固醇，植物细胞为豆固醇，真菌细胞为麦角固醇，多数细菌质膜不含固醇。", "page": 11, "level": "掌握", "img": "assets/img/ch02/p011.jpg", "anim": null, "fig": null, "points": null}, {"i": 10, "sec": "第一节 膜的组成", "title": "血型抗原 (p12)", "notes": "Blood group antigens：A、B、AB、O血型由红细胞膜上糖脂/糖蛋白的寡糖链决定，是膜糖类参与细胞识别与免疫的经典例子。", "page": 12, "level": "理解", "img": "assets/img/ch02/p012.jpg", "anim": null, "fig": "ABO 血型抗原由糖脂的糖链决定：O 型为基础糖链，A 型加 N-乙酰半乳糖胺，B 型加半乳糖。图显示糖链末端糖基的差异决定血型，说明糖脂的糖基位于质膜外侧、参与细胞识别。", "points": null}, {"i": 11, "sec": "第一节 膜的组成", "title": "膜脂的不对称性 (p13-15)", "notes": "膜脂在细胞内外两侧分布不对称：①磷脂、糖脂分布表现完全不对称性——糖脂位于细胞外侧(非胞质侧)；②胆固醇几乎均等地分布在两侧单层；③糖蛋白和糖脂的糖基部分均位于质膜外侧(非胞质面)；④膜脂不对称性指同一种膜脂分布在两侧的比例不同。膜脂和膜蛋白在生物膜上均呈不对称分布。", "page": 13, "level": "掌握", "img": "assets/img/ch02/p013.jpg", "anim": "lipid_asymmetry", "fig": null, "points": null}, {"i": 12, "sec": "第一节 膜的组成", "title": "膜脂的运动性 (p16)", "notes": "膜脂运动方式：①同一侧的侧向运动(基本运动方式)；②双层分子之间的翻转运动(flip-flop，较慢)；③尾部摆动；④绕轴心自旋。运动性赋予膜流动性。", "page": 16, "level": "掌握", "img": "assets/img/ch02/p016.jpg", "anim": "membrane_fluidity", "fig": null, "points": null}, {"i": 13, "sec": "第一节 膜的组成", "title": "膜脂的特性 (p17)", "notes": "膜脂两大特性：①不对称性；②流动性(Membrane Fluidity)→可塑性/伸缩性，使膜能变形、融合、分裂。", "page": 17, "level": "掌握", "img": "assets/img/ch02/p017.jpg", "anim": null, "fig": null, "points": null}, {"i": 14, "sec": "第一节 膜的组成", "title": "膜的动态特性 (p18)", "notes": "The dynamics properties of the plasma membrane：运动细胞的前缘、膜蛋白的移动等体现膜的动态性。膜流动性是细胞进行生命活动的必要条件。", "page": 18, "level": "理解", "img": "assets/img/ch02/p018.jpg", "anim": null, "fig": null, "points": null}, {"i": 15, "sec": "第一节 膜的组成", "title": "两性分子自装配成脂双层 (p19-20)", "notes": "膜脂具有一个亲水头部和一到两条疏水尾部，是两性物质。在水溶液中能自动、自我装配形成脂双分子层，总是形成连续、不破裂的结构。疏水尾部不带电荷、无极性、不能与水形成氢键，暴露于水中能量上不利→自发把尾部埋在内侧、头部朝向水。", "page": 19, "level": "掌握", "img": "assets/img/ch02/p019.jpg", "anim": "lipid_selfassembly", "fig": null, "points": null}, {"i": 16, "sec": "第一节 膜的组成", "title": "脂质体 (p21)", "notes": "脂质体(liposome)：人工把纯磷脂/磷脂酰胆碱加入水中，可自我装配形成封闭的、直径25nm-1mm的球形小泡。电镜可显示其脂双层结构。是研究膜的良好模型。", "page": 21, "level": "掌握", "img": "assets/img/ch02/p021.jpg", "anim": null, "fig": "脂质体(liposome)：磷脂在水溶液中自发形成的封闭双层囊泡，内部包裹水相。可用来运载药物(DNA/蛋白)。图显示脂质体的双层结构与内部空腔。", "points": null}, {"i": 17, "sec": "第一节 膜的组成", "title": "脂质体的应用 (p22-23)", "notes": "脂质体应用：①生物膜特性研究模型(膜蛋白可插入脂质体)；②抗体分子可使脂质体选择性结合到细胞表面→药物靶向递送；③膜蛋白功能研究、药物载体、疫苗佐剂等。", "page": 22, "level": "理解", "img": "assets/img/ch02/p022.jpg", "anim": null, "fig": null, "points": null}, {"i": 18, "sec": "第一节 膜的组成", "title": "膜脂的功能 (p24)", "notes": "膜脂的功能：①构成膜的基本骨架；②也是膜蛋白执行功能的场所——蛋白通过疏水端同膜脂作用，使蛋白镶嵌在膜上执行功能；③一般情况下膜脂本身不参与生化生理功能(但有些膜脂如PI参与信号转导)。", "page": 24, "level": "掌握", "img": "assets/img/ch02/p024.jpg", "anim": null, "fig": null, "points": null}, {"i": 19, "sec": "第一节 膜的组成", "title": "膜蛋白 (p25)", "notes": "膜蛋白：生物膜的特定功能主要由蛋白质决定。一般功能越复杂的膜，其膜蛋白种类越多。按与膜结合方式分为：①膜内在蛋白/跨膜蛋白(intrinsic/integral)；②外周膜蛋白；③脂锚定蛋白。", "page": 25, "level": "掌握", "img": "assets/img/ch02/p025.jpg", "anim": "membrane_protein_types", "fig": null, "points": null}, {"i": 20, "sec": "第一节 膜的组成", "title": "去垢剂 (p26-27)", "notes": "去垢剂(detergent)用于溶解膜蛋白：①离子型去垢剂(如SDS)——高浓度可破坏蛋白质离子键和氢键等非共价键，甚至改变亲水部分构象；②非离子型去垢剂(如Triton X-100)——温和，可溶解膜蛋白并保持活性。利用Triton X-100等温和去垢剂溶解膜蛋白是分离纯化的常用方法。", "page": 26, "level": "掌握", "img": "assets/img/ch02/p026.jpg", "anim": null, "fig": "去垢剂(如 SDS、Triton X-100)能插入膜并破坏疏水作用，把膜蛋白溶解下来。图显示去垢剂分子包裹膜蛋白的疏水区，使其保持可溶。去垢剂是膜蛋白提取和研究的常用试剂。", "points": null}, {"i": 21, "sec": "第一节 膜的组成", "title": "内在跨膜整合蛋白 (p28)", "notes": "膜内在蛋白(integral/intrinsic protein)：以α-螺旋或β-折叠方式跨膜。如跨膜受体、通道蛋白、载体蛋白；细菌外膜上的孔蛋白以β-折叠跨膜。", "page": 28, "level": "掌握", "img": "assets/img/ch02/p028.jpg", "anim": "tm_protein_structure", "fig": "跨膜蛋白的两种常见跨膜结构：①α 螺旋——疏水氨基酸侧链朝外、与脂尾作用，是最常见的跨膜方式；②β 桶——β 折叠卷成桶状，见于孔道蛋白(如孔蛋白)。图对比两种跨膜结构。", "points": null}, {"i": 22, "sec": "第一节 膜的组成", "title": "胰岛素跨膜受体 (p29)", "notes": "胰岛素跨膜受体：典型的跨膜受体蛋白，含胞外配体结合区、跨膜区、胞内激酶区，是膜内在蛋白的实例。", "page": 29, "level": "理解", "img": "assets/img/ch02/p029.jpg", "anim": null, "fig": "胰岛素受体是单次跨膜的受体酪氨酸激酶：胞外结合胰岛素，跨膜段固定，胞内激酶域自磷酸化后启动信号。图说明跨膜蛋白可把胞外信号传到胞内，是“膜的信息传递功能”实例。", "points": null}, {"i": 23, "sec": "第一节 膜的组成", "title": "外周膜蛋白 (p30-31)", "notes": "外周膜蛋白(peripheral proteins)：以非共价键结合在膜脂极性头部或膜内在蛋白上。人红细胞膜骨架蛋白中的血影蛋白、肌动蛋白属于外周蛋白。电镜显示其在膜内侧形成网状骨架。", "page": 30, "level": "掌握", "img": "assets/img/ch02/p030.jpg", "anim": null, "fig": null, "points": null}, {"i": 24, "sec": "第一节 膜的组成", "title": "脂锚定蛋白 (p32)", "notes": "脂锚定蛋白：与膜脂的特定脂类以共价连接于膜上。虽位于外周，但改变pH或离子强度不能从膜上去除，需特定的酶才能释放。如小G蛋白(Ras等)。", "page": 32, "level": "掌握", "img": "assets/img/ch02/p032.jpg", "anim": "lipid_anchors", "fig": "脂锚定蛋白通过脂质锚连在膜上：①GPI 锚定蛋白——锚在膜外侧；②Src 等——N 端豆蔻酰化/棕榈酰化锚在胞质侧；③Ras——C 端异戊二烯化。图对比三种脂锚定方式。", "points": null}, {"i": 25, "sec": "第一节 膜的组成", "title": "膜蛋白的分离 (p33)", "notes": "如何分离各种类型膜蛋白？——根据膜蛋白与膜结合方式：外周蛋白可用高盐/改变pH/离子强度洗脱；内在蛋白需去垢剂溶解；脂锚定蛋白需特定酶(如磷脂酶)释放。", "page": 33, "level": "理解", "img": "assets/img/ch02/p033.jpg", "anim": null, "fig": "膜蛋白的分离：外周膜蛋白用高盐/极端 pH 即可洗脱；整合膜蛋白需去垢剂或有机溶剂破坏脂双层。图对比外周蛋白(松散结合)与整合蛋白(嵌入疏水区)的分离条件。", "points": null}, {"i": 26, "sec": "第一节 膜的组成", "title": "限制膜蛋白侧向运动的因素 (p34)", "notes": "膜蛋白的运动及限制膜蛋白侧向运动的4种方式：①胞内骨架成分；②细胞外基质中的分子；③其他扩散屏障(如紧密连接)；④膜蛋白与其它膜蛋白/脂筏的结合。", "page": 34, "level": "掌握", "img": "assets/img/ch02/p034.jpg", "anim": null, "fig": "膜蛋白的运动受限制：①被细胞骨架锚定；②被细胞外基质连接；③与其他细胞连接形成屏障；④形成大复合体。图显示膜蛋白并非完全自由扩散，其运动受多种因素约束。", "points": null}, {"i": 27, "sec": "第一节 膜的组成", "title": "上皮细胞极性 (p35)", "notes": "肠内壁上皮细胞：面向肠腔的表面为细胞顶端表面(protein A朝向)；朝向组织和血液的为基底和侧面(转运蛋白B)。膜蛋白的不对称分布决定了细胞极性——上皮细胞顶端与基底面的蛋白组成不同。", "page": 35, "level": "理解", "img": "assets/img/ch02/p035.jpg", "anim": null, "fig": "上皮细胞的极性：顶面(apical)和基底面(basolateral)的膜蛋白/脂质组成不同，由紧密连接(tight junction)分隔，防止膜蛋白扩散。图显示极性细胞的顶-底膜蛋白分布差异。", "points": null}, {"i": 28, "sec": "第一节 膜的组成", "title": "膜的流动性 (p36)", "notes": "膜的流动性——膜脂的流动性和膜蛋白的运动是细胞进行生命活动的必要条件。膜流动性使细胞能进行物质运输、信号转导、细胞融合、分裂等。", "page": 36, "level": "掌握", "img": "assets/img/ch02/p036.jpg", "anim": "cell_fusion", "fig": null, "points": null}, {"i": 29, "sec": "第一节 膜的组成", "title": "FRAP技术 (p37)", "notes": "荧光漂白恢复技术(FRAP, Fluorescence Recovery After Photo-bleaching)：用荧光标记膜蛋白/膜脂→激光漂白局部区域→观察荧光恢复速度→测定膜分子的扩散速率，是研究膜流动性的经典方法。", "page": 37, "level": "掌握", "img": "assets/img/ch02/p037.jpg", "anim": "frap", "fig": "荧光漂白恢复(FRAP)实验：用激光漂白膜上一小块荧光标记的蛋白，观察周围荧光扩散回来恢复的速度，从而测膜蛋白的流动性。图显示漂白区荧光逐渐恢复，证明膜是流动的。", "points": null}, {"i": 30, "sec": "第一节 膜的组成", "title": "影响膜流动性的因素-温度 (p38)", "notes": "3.1 温度——最主要的影响因素。37℃以上膜脂相对流动的液态存在；温度降低到某一点时，膜脂由液晶(流动)态转变为凝胶态(相变温度Tm)。温度越高，流动性越大。", "page": 38, "level": "掌握", "img": "assets/img/ch02/p038.jpg", "anim": null, "fig": null, "points": null}, {"i": 31, "sec": "第一节 膜的组成", "title": "脂肪酸尾部的聚集 (p39)", "notes": "尾部聚集得越密集、越有规则，该双层越粘滞，流动性越少。饱和脂肪酸尾部排列紧密→流动性低。", "page": 39, "level": "理解", "img": "assets/img/ch02/p039.jpg", "anim": null, "fig": null, "points": null}, {"i": 32, "sec": "第一节 膜的组成", "title": "膜脂结构组成对流动性的影响 (p40)", "notes": "3.2 膜脂结构和组成对膜流动性的影响：①脂肪酸链的长度——短链脂肪酸含量丰富，膜流动性高；②脂肪酸链的不饱和程度——不饱和度高(双键多)流动性高；③胆固醇——调节流动性。", "page": 40, "level": "掌握", "img": "assets/img/ch02/p040.jpg", "anim": null, "fig": null, "points": null}, {"i": 33, "sec": "第一节 膜的组成", "title": "卵磷脂分子 (p41)", "notes": "卵磷脂分子(磷脂酰胆碱)：膜脂的典型代表，一个极性头(胆碱+磷酸+甘油)+两条疏水尾(脂肪酸链)。", "page": 41, "level": "理解", "img": "assets/img/ch02/p041.jpg", "anim": null, "fig": null, "points": null}, {"i": 34, "sec": "第一节 膜的组成", "title": "饱和与不饱和脂肪酸 (p42)", "notes": "饱和脂肪酸(猪肉、奶制品)不含双键→分子间排列紧密→室温下固态；不饱和脂肪酸(植物油如玉米油)含双键→分子弯曲、排列疏松→室温下液态。这解释了膜流动性与脂肪酸饱和度的关系。", "page": 42, "level": "掌握", "img": "assets/img/ch02/p042.jpg", "anim": null, "fig": "脂肪酸的饱和度影响膜的流动性：饱和脂肪酸(如硬脂酸)直链排列紧密，降低流动性；不饱和脂肪酸(含双键)弯曲、排列疏松，提高流动性。图对比两种尾部对脂双层排列的影响。", "points": null}, {"i": 35, "sec": "第一节 膜的组成", "title": "固醇结构 (p43)", "notes": "固醇(甾醇)：基本结构是4环碳氢化合物。动物为胆固醇，植物为豆固醇/豆甾醇，真菌为麦角固醇。", "page": 43, "level": "理解", "img": "assets/img/ch02/p043.jpg", "anim": null, "fig": null, "points": null}, {"i": 36, "sec": "第一节 膜的组成", "title": "胆固醇在膜中的位置 (p44)", "notes": "胆固醇分子(绿色)插入脂双层中：甾环区与磷脂的脂肪酸链相互作用，羟基朝向水相。胆固醇调节膜的流动性和稳定性。", "page": 44, "level": "理解", "img": "assets/img/ch02/p044.jpg", "anim": null, "fig": "胆固醇嵌在磷脂之间：其刚性环状结构使膜脂排列更有序，在高温下限制运动、低温下阻止紧密堆积。图显示胆固醇位于疏水尾部区域，是“流动性缓冲器”。", "points": null}], "mcq": [{"id": "ch02_mcq_1", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "生物膜流动镶嵌模型的提出者和年份是？", "o": ["A. Singer & Nicolson,1972", "B. Watson & Crick,1953", "C. Robertson,1964", "D. Singer,1988"], "a": "A", "e": "1972年Singer和Nicolson提出流动镶嵌模型：磷脂双分子层为基本骨架，蛋白质镶嵌其中，膜具流动性。", "kp": "ch02_s0_2"}, {"id": "ch02_mcq_2", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "占整个膜脂50%以上的膜脂是？", "o": ["A. 胆固醇", "B. 甘油磷脂", "C. 鞘脂", "D. 糖脂"], "a": "B", "e": "甘油磷脂为膜脂基本成分，占整个膜脂50%以上。包括磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇。", "kp": "ch02_s0_7"}, {"id": "ch02_mcq_3", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "关于胆固醇在膜中的作用,错误的是？", "o": ["A. 自身不能形成脂双层", "B. 调节膜的流动性", "C. 是脂筏基本结构成分", "D. 是膜脂含量最高的成分"], "a": "D", "e": "胆固醇自身不能形成脂双层，只能插入磷脂之间；调节流动性、增加稳定性；是脂筏成分。含量最高的膜脂是甘油磷脂。", "kp": "ch02_s0_36"}, {"id": "ch02_mcq_4", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "膜脂运动的基本方式是？", "o": ["A. 翻转运动", "B. 侧向运动", "C. 尾部摆动", "D. 自旋"], "a": "B", "e": "同一侧的侧向运动是膜脂运动的基本方式。翻转运动(flip-flop)较慢，需酶协助。", "kp": "ch02_s0_12"}, {"id": "ch02_mcq_5", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "膜脂和膜蛋白在膜上的分布特点是？", "o": ["A. 完全对称", "B. 不对称分布", "C. 随机分布", "D. 只在胞外侧"], "a": "B", "e": "膜脂和膜蛋白在生物膜上均呈不对称分布；糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。", "kp": "ch02_s0_11"}, {"id": "ch02_mcq_6", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "膜内在蛋白(integral protein)的跨膜方式是？", "o": ["A. 仅α-螺旋", "B. α-螺旋或β-折叠", "C. 仅β-折叠", "D. 无规则"], "a": "B", "e": "内在跨膜整合蛋白以α-螺旋或β-折叠方式跨膜；细菌外膜孔蛋白以β-折叠跨膜。", "kp": "ch02_s0_21"}, {"id": "ch02_mcq_7", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "人红细胞膜骨架蛋白中的血影蛋白属于？", "o": ["A. 内在蛋白", "B. 外周蛋白", "C. 脂锚定蛋白", "D. 通道蛋白"], "a": "B", "e": "血影蛋白、肌动蛋白以非共价键结合在膜内侧，属于外周膜蛋白，构成膜骨架。", "kp": "ch02_s0_23"}, {"id": "ch02_mcq_8", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "需要用特定酶才能从膜上释放的膜蛋白是？", "o": ["A. 外周蛋白", "B. 脂锚定蛋白", "C. 内在蛋白", "D. 跨膜蛋白"], "a": "B", "e": "脂锚定蛋白与膜脂共价连接，改变pH或离子强度不能去除，需特定酶(如磷脂酶)才能释放。", "kp": "ch02_s0_24"}, {"id": "ch02_mcq_9", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "影响膜流动性最主要的因素是？", "o": ["A. pH", "B. 温度", "C. 离子强度", "D. 膜蛋白种类"], "a": "B", "e": "温度是影响膜流动性最主要的因素。温度降低到相变温度时膜脂由液晶态转变为凝胶态。", "kp": "ch02_s0_30"}, {"id": "ch02_mcq_10", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "下列关于膜流动性的说法正确的是？", "o": ["A. 脂肪酸链越长流动性越高", "B. 不饱和脂肪酸越多流动性越高", "C. 胆固醇总是增加流动性", "D. 饱和脂肪酸越多流动性越高"], "a": "B", "e": "短链脂肪酸、不饱和脂肪酸(双键多)使流动性高；长链、饱和脂肪酸降低流动性；胆固醇双向调节。", "kp": "ch02_s0_30"}, {"id": "ch02_mcq_11", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "研究膜分子扩散速率的经典技术是？", "o": ["A. FRAP", "B. PCR", "C. SDS-PAGE", "D. 电镜"], "a": "A", "e": "荧光漂白恢复技术(FRAP)：标记→激光漂白→观察荧光恢复→测定扩散速率。", "kp": "ch02_s0_29"}, {"id": "ch02_mcq_12", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "人工脂双层对下列哪种物质通透性最低？", "o": ["A. O2", "B. H2O", "C. 葡萄糖", "D. Na+等离子"], "a": "D", "e": "离子几乎不能通过人工脂双层，需通道/载体蛋白。通透性：疏水分子>小极性分子>大极性分子>离子。", "kp": "ch02_s0_15"}, {"id": "ch02_mcq_13", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "通道蛋白的特点是？", "o": ["A. 需与运输分子结合", "B. 只参与被动运输,转运速率最快", "C. 逆浓度梯度运输", "D. 需消耗ATP"], "a": "B", "e": "通道蛋白形成亲水通道，不需与底物结合，只参与被动运输，转运速率最快；有电压/配体/应力三种门控。", "kp": "ch02_s0_25"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "流动镶嵌模型由Singer和Nicolson于1972年提出。", "a": "对", "e": "1972年Singer和Nicolson提出流动镶嵌模型，是膜结构研究的里程碑。", "kp": "ch02_s0_2"}, {"id": "ch02_judge_2", "modI": 0, "q": "甘油磷脂是膜脂中含量最高的成分，占膜脂50%以上。", "a": "对", "e": "甘油磷脂为膜脂基本成分，占整个膜脂50%以上。", "kp": "ch02_s0_7"}, {"id": "ch02_judge_3", "modI": 0, "q": "胆固醇自身能形成脂双层，是构成膜骨架的主要成分。", "a": "错", "e": "胆固醇自身不能形成脂双层，只能插入磷脂分子之间，起调节流动性等作用。", "kp": "ch02_s0_9"}, {"id": "ch02_judge_4", "modI": 0, "q": "膜脂和膜蛋白在膜上呈不对称分布，糖脂的糖基位于细胞外侧。", "a": "对", "e": "膜脂、膜蛋白均呈不对称分布；糖蛋白和糖脂的糖基位于质膜外侧(非胞质面)。", "kp": "ch02_s0_11"}, {"id": "ch02_judge_5", "modI": 0, "q": "温度降低到相变温度以下时，膜脂由液晶态转变为凝胶态，流动性降低。", "a": "对", "e": "温度是影响膜流动性最主要的因素；降至相变温度以下膜脂由液晶态变凝胶态。", "kp": "ch02_s0_30"}, {"id": "ch02_judge_6", "modI": 0, "q": "不饱和脂肪酸含量越高，膜流动性越低。", "a": "错", "e": "不饱和脂肪酸含双键、分子弯曲、排列疏松，含量越高流动性越高。", "kp": "ch02_s0_34"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "生物膜流动镶嵌模型由________和________于________年提出。", "a": "Singer,Nicolson,1972", "kp": "ch02_s0_2"}, {"id": "ch02_fill_2", "modI": 0, "q": "膜脂三大类是________、________和________,都是________分子。", "a": "甘油磷脂,鞘脂,胆固醇,两性", "kp": "ch02_s0_6"}, {"id": "ch02_fill_3", "modI": 0, "q": "占膜脂50%以上的是________；不能自身形成脂双层、只能插入磷脂之间的是________。", "a": "甘油磷脂,胆固醇", "kp": "ch02_s0_15"}, {"id": "ch02_fill_4", "modI": 0, "q": "膜脂运动的基本方式是________；双层分子间的________运动较慢。", "a": "侧向运动,翻转(flip-flop)", "kp": "ch02_s0_12"}, {"id": "ch02_fill_5", "modI": 0, "q": "膜内在蛋白以________或________方式跨膜；外周蛋白以________键结合在膜上。", "a": "α-螺旋,β-折叠,非共价", "kp": "ch02_s0_21"}, {"id": "ch02_fill_6", "modI": 0, "q": "影响膜流动性最主要的因素是________；不饱和脂肪酸越多,流动性越________。", "a": "温度,高", "kp": "ch02_s0_30"}, {"id": "ch02_fill_12", "modI": 0, "q": "脂筏是膜上________、________等富集的微区域,1988年提出________模型。", "a": "胆固醇,鞘磷脂,脂筏(Lipid raft)", "kp": "ch02_s0_4"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述生物膜流动镶嵌模型的主要内容。", "a": "流动镶嵌模型(1972, Singer & Nicolson)主要内容：\n\n①磷脂双分子层是生物膜的基本结构组分——磷脂具有极性头部(亲水)和非极性尾部(疏水)，在水溶液中自动装配成脂双层；\n②膜蛋白以不同方式镶嵌于脂双层：内在蛋白(跨膜)、外周蛋白(非共价结合)、脂锚定蛋白(共价连接)；\n③膜脂和膜蛋白具有流动性——膜脂可侧向运动、翻转、摆动、自旋；膜蛋白可侧向扩散；\n④膜脂和膜蛋白分布具有不对称性——糖脂/糖蛋白的糖基位于质膜外侧；\n⑤脂类与蛋白质的流动性和不对称性是它们相互作用及与其他生物大分子相互作用的基础；\n⑥这种相互作用又一定程度上限制了膜蛋白和膜脂的流动性。\n\n【发展】此后提出脂筏模型(1988)：膜上胆固醇、鞘磷脂富集形成相对独立的微区域。\n【意义】解释了膜的许多性质：物质运输、信号转导、细胞融合等。", "kp": "ch02_s0_2"}, {"id": "ch02_short_2", "modI": 0, "q": "简述膜脂的种类、特性及其对膜流动性的影响。", "a": "膜脂分三大类：\n①甘油磷脂(占膜脂50%以上)：磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇；\n②鞘脂：鞘氨醇衍生物，分鞘磷脂、鞘糖脂，主要在高尔基体合成；\n③胆固醇：4环碳氢化合物，自身不能形成脂双层，插入磷脂之间。\n都是两性分子(亲水头+疏水尾)。\n\n膜脂特性：\n①不对称性——磷脂、糖脂分布完全不对称，糖脂位于胞外侧，胆固醇均等分布；\n②流动性——侧向运动(基本)、翻转、尾部摆动、自旋。\n\n影响膜流动性的因素：\n①温度(最主要)——温度高流动性大，降至相变温度以下变凝胶态；\n②脂肪酸链长度——短链流动性高；\n③不饱和程度——不饱和度高(双键多)流动性高；\n④胆固醇——双向调节(相变温度以上降低流动性、以下防止凝固)。", "kp": "ch02_s0_32"}, {"id": "ch02_short_3", "modI": 0, "q": "简述膜蛋白的类型及分离方法。", "a": "膜蛋白类型(按与膜结合方式)：\n\n①膜内在蛋白/跨膜蛋白(intrinsic/integral)：以α-螺旋或β-折叠跨膜，如跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白。\n②外周膜蛋白(peripheral)：以非共价键结合在膜脂极性头部或内在蛋白上，如红细胞膜骨架的血影蛋白、肌动蛋白。\n③脂锚定蛋白：与膜脂特定脂类共价连接，虽位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放，如小G蛋白。\n\n分离方法：\n①外周蛋白——高盐、改变pH或离子强度可洗脱；\n②内在蛋白——需去垢剂(离子型如SDS，非离子型如Triton X-100)溶解；\n③脂锚定蛋白——需特定酶释放。\n\n去垢剂：离子型(SDS)破坏非共价键、可能变性；非离子型(Triton X-100)温和、保持活性。", "kp": "ch02_s0_25"}], "calc": [{"id": "ch02_calc_1", "modI": 0, "q": "论述生物膜的不对称性及其生物学意义。", "a": "膜脂和膜蛋白的不对称分布是生物膜的基本特征,具有重要功能意义", "steps": "【不对称性的表现】\n①膜脂：磷脂、糖脂分布完全不对称——糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布在两侧；同一种膜脂两侧比例不同。\n②膜蛋白：分布不对称——如肠上皮细胞顶端面与基底面的转运蛋白不同(protein A、B)。\n③糖类：糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。\n\n【生物学意义】\n①决定细胞极性——上皮细胞顶端与基底面功能不同(吸收vs转运)；\n②细胞识别与免疫——糖基位于外侧，血型抗原(A/B/AB/O)由膜糖脂/糖蛋白决定；\n③信号转导——受体、G蛋白等不对称分布，保证信号方向性；\n④物质运输——载体/通道蛋白定向分布，实现跨细胞转运(如小肠吸收葡萄糖)；\n⑤细胞融合、分裂、运动的基础。\n\n【结论】不对称性与流动性共同构成生物膜的两大特征，是膜功能多样性的分子基础。", "kp": "ch02_s0_11"}, {"id": "ch02_calc_3", "modI": 0, "q": "论述膜流动性及其影响因素和生物学意义。", "a": "膜流动性是生物膜的基本特征,由多种因素调节,是生命活动的必要条件", "steps": "【流动性的表现】\n膜脂：侧向运动(基本)、翻转运动(慢)、尾部摆动、绕轴自旋；膜蛋白：侧向扩散。\n\n【影响因素】\n①温度(最主要)：温度高流动性大；降至相变温度以下，膜脂由液晶态→凝胶态；\n②脂肪酸链长度：短链含量高→流动性高；\n③不饱和程度：不饱和脂肪酸(双键多)使分子弯曲、排列疏松→流动性高；饱和脂肪酸排列紧密→流动性低；\n④胆固醇：双向调节——相变温度以上减弱脂肪酸链运动、降低流动性；以下阻止紧密排列、防止凝固；\n⑤膜蛋白与骨架的限制。\n\n【研究方法】FRAP(荧光漂白恢复)测定扩散速率。\n\n【生物学意义】\n①物质运输：膜融合、胞吞胞吐；\n②信号转导：受体聚集、脂筏动态；\n③细胞运动、分裂、融合；\n④膜蛋白功能发挥。\n\n【结论】膜流动性使细胞能进行各种生命活动，是细胞生存的必要条件。", "kp": "ch02_s0_30"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "流动镶嵌模型(Fluid Mosaic Model)", "def": "①1972年Singer和Nicolson提出的生物膜结构模型（定义）。②内容：磷脂双分子层为基本骨架；膜蛋白以不同方式镶嵌其中；膜脂和膜蛋白具流动性；分布具不对称性（内容）。③意义：解释膜的多种性质(运输、信号、融合)，是膜生物学的里程碑（意义）。", "kps": "踩分点:①提出者年份(1分)②内容(2分)③意义(1分)", "kp": "ch02_s0_2"}, {"id": "ch02_term_2", "modI": 0, "term": "脂筏(Lipid Raft)", "def": "①膜上胆固醇、鞘磷脂等富集形成的相对独立的微区域(1988提出)（定义）。②特点：异质性、高度动态、分子排列较紧密（特点）。③组成：含250多种蛋白；非离子去垢剂(如Triton X-100)可分离（组成）。④功能：参与细胞信息传递、物质运输等（功能）。", "kps": "踩分点:①定义(1分)②特点(1分)③组成(1分)④功能(1分)", "kp": "ch02_s0_4"}, {"id": "ch02_term_3", "modI": 0, "term": "膜脂的不对称性", "def": "①同一种膜脂在脂双层两侧分布比例不同、呈不对称分布的现象（定义）。②表现：磷脂、糖脂分布完全不对称，糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布（表现）。③意义：决定细胞极性、细胞识别(血型抗原)、信号转导方向性（意义）。", "kps": "踩分点:①定义(1分)②表现(2分)③意义(1分)", "kp": "ch02_s0_11"}, {"id": "ch02_term_4", "modI": 0, "term": "膜流动性(Membrane Fluidity)", "def": "①膜脂和膜蛋白在膜内运动的能力（定义）。②膜脂运动方式：侧向运动(基本)、翻转、尾部摆动、自旋（方式）。③影响因素：温度(最主要)、脂肪酸链长度、不饱和程度、胆固醇（因素）。④意义：是细胞进行物质运输、信号转导、融合、分裂等生命活动的必要条件（意义）。", "kps": "踩分点:①定义(1分)②运动方式(1分)③影响因素(1分)④意义(1分)", "kp": "ch02_s0_13"}, {"id": "ch02_term_5", "modI": 0, "term": "膜内在蛋白(Integral Protein)", "def": "①与膜脂疏水区紧密结合、需去垢剂才能溶解的膜蛋白（定义）。②跨膜方式：α-螺旋或β-折叠（方式）。③举例：跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白（举例）。④分离：需离子型/非离子型去垢剂溶解（分离）。", "kps": "踩分点:①定义(1分)②跨膜方式(1分)③举例(1分)④分离(1分)", "kp": "ch02_s0_21"}, {"id": "ch02_term_6", "modI": 0, "term": "外周膜蛋白(Peripheral Protein)", "def": "①以非共价键结合在膜脂极性头部或内在蛋白上的膜蛋白（定义）。②特点：不插入脂双层疏水区（特点）。③举例：红细胞膜骨架的血影蛋白、肌动蛋白（举例）。④分离：高盐、改变pH或离子强度可洗脱（分离）。", "kps": "踩分点:①定义(1分)②特点(1分)③举例(1分)④分离(1分)", "kp": "ch02_s0_23"}, {"id": "ch02_term_7", "modI": 0, "term": "脂锚定蛋白", "def": "①与膜脂特定脂类以共价键连接于膜上的膜蛋白（定义）。②特点：位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放（特点）。③举例：小G蛋白(Ras等)（举例）。", "kps": "踩分点:①定义(1分)②特点(2分)③举例(1分)", "kp": "ch02_s0_24"}, {"id": "ch02_term_8", "modI": 0, "term": "脂质体(Liposome)", "def": "①人工把纯磷脂/磷脂酰胆碱加入水中自我装配形成的封闭球形小泡，直径25nm-1mm（定义）。②结构：脂双层包围水相（结构）。③应用：生物膜研究模型、膜蛋白研究、药物靶向递送载体（应用）。", "kps": "踩分点:①定义(1分)②结构(1分)③应用(2分)", "kp": "ch02_s0_16"}, {"id": "ch02_term_9", "modI": 0, "term": "去垢剂(Detergent)", "def": "①能溶解膜蛋白的两亲性物质（定义）。②分类：离子型(如SDS)——破坏非共价键、可能变性；非离子型(如Triton X-100)——温和、保持活性（分类）。③用途：溶解膜内在蛋白、分离纯化膜蛋白（用途）。", "kps": "踩分点:①定义(1分)②分类(2分)③用途(1分)", "kp": "ch02_s0_20"}]}, {"i": 1, "name": "模块二：跨膜运输", "slides": [{"i": 0, "sec": "第一节 膜的组成", "title": "胆固醇对流动性的调节 (p45)", "notes": "胆固醇对细胞膜磷脂分子流动性的调节作用随温度不同而改变：相变温度以上，它能使磷脂的脂肪酸链运动性减弱，从而降低细胞膜磷脂分子的流动性；相变温度以下，它又能阻止脂肪酸链紧密排列，防止膜凝固。胆固醇是膜流动性的'缓冲器'。", "page": 45, "level": "掌握", "img": "assets/img/ch02/p045.jpg", "anim": null, "fig": "胆固醇对膜流动性的双向调节：温度较高时，胆固醇限制磷脂运动、降低流动性；温度较低时，胆固醇阻止磷脂尾紧密堆积、维持流动性。图给出流动性-温度曲线在有无胆固醇时的差异。", "points": null}, {"i": 1, "sec": "第二节 跨膜运输", "title": "跨膜运输的途径 (p46)", "notes": "跨膜运输的途径：①被动运输(passive transport)——顺浓度梯度，不需能量；②主动运输(active transport)——逆浓度梯度，需能量。Transmembrane Transport of Ions and Small Molecules。", "page": 46, "level": "掌握", "img": "assets/img/ch02/p046.jpg", "anim": null, "fig": null, "points": null}, {"i": 2, "sec": "第二节 跨膜运输", "title": "人工脂双层的通透性 (p47)", "notes": "Permeability of a synthetic lipid bilayer：人工脂双层对小分子/离子的通透性不同。疏水分子(O2、CO2、N2、激素)易通过；小的不带电极性分子(H2O、尿素、甘油)较易；大的不带电极性分子(葡萄糖、蔗糖)难通过；离子(Na+、K+、Cl-)几乎不能通过。", "page": 47, "level": "掌握", "img": "assets/img/ch02/p047.jpg", "anim": "membrane_permeability", "fig": "人工膜对物质的通透性顺序：疏水小分子(O₂、CO₂、苯)易透过；水、尿素次之；葡萄糖、离子(Na⁺、K⁺)难透过。图用透过速率排序，说明“越小越疏水越易透过”。", "points": null}, {"i": 3, "sec": "第二节 跨膜运输", "title": "水的极性 (p48)", "notes": "共价键中电子共享不均等时产生极性和部分正、负电荷，如水(H2O)。水是极性分子，虽小但跨膜需水通道。", "page": 48, "level": "理解", "img": "assets/img/ch02/p048.jpg", "anim": null, "fig": null, "points": null}, {"i": 4, "sec": "第二节 跨膜运输", "title": "被动运输 (p49)", "notes": "选择性的跨膜物质运输。1)被动运输——顺浓度梯度：①简单扩散——不需要能量、不需载体，如O2、CO2；②协助扩散——需载体/通道蛋白，顺浓度梯度，不耗能。", "page": 49, "level": "掌握", "img": "assets/img/ch02/p049.jpg", "anim": "facilitated_diffusion", "fig": null, "points": null}, {"i": 5, "sec": "第二节 跨膜运输", "title": "通道蛋白 (p50)", "notes": "通道蛋白：在膜上形成跨膜的亲水通道，使离子从中通过，不需要与运输分子结合。只参与被动运输，转运速率最快。三种门控：膜电压门控、配体门控、应力门控。", "page": 50, "level": "掌握", "img": "assets/img/ch02/p050.jpg", "anim": "channel_gating", "fig": "通道蛋白的门控机制：①电压门控(膜电位变化)；②配体门控(配体结合)；③机械门控(机械力)。图对比三种门控方式。通道只开放时才能通透，且不与被转运物结合。", "points": null}, {"i": 6, "sec": "第二节 跨膜运输", "title": "葡萄糖协助扩散 (p51-52)", "notes": "动物细胞葡萄糖的协助扩散：载体蛋白GLUT家族通过构象变化将葡萄糖运到细胞内。Glut1介导葡萄糖进入红细胞(维持血糖浓度稳定)、通过血脑屏障。除脂溶性分子和小的不带电分子以简单扩散通过外，几乎所有小有机分子及无机离子穿过细胞膜都需膜蛋白协助。", "page": 51, "level": "掌握", "img": "assets/img/ch02/p051.jpg", "anim": null, "fig": "GLUT(葡萄糖载体)通过构象变化转运葡萄糖：结合葡萄糖 → 构象改变 → 把葡萄糖释放到膜另一侧。图显示 GLUT 的“交替构象”模型，属易化扩散(顺浓度梯度、不耗能)。", "points": null}, {"i": 7, "sec": "第二节 跨膜运输", "title": "ADP/ATP载体蛋白 (p53)", "notes": "线粒体内膜上的ADP/ATP载体蛋白：交换ADP(进)和ATP(出)，是小分子膜蛋白，属于载体蛋白介导的跨膜运输。", "page": 53, "level": "理解", "img": "assets/img/ch02/p053.jpg", "anim": "atp_adp_carrier", "fig": null, "points": null}, {"i": 8, "sec": "第二节 跨膜运输", "title": "2003年诺贝尔化学奖 (p54)", "notes": "2003年诺贝尔化学奖授予物质跨膜运输研究——水通道及钾离子通道：Peter Agre(发现水通道)和Roderick MacKinnon(钾通道结构)。", "page": 54, "level": "掌握", "img": "assets/img/ch02/p054.jpg", "anim": null, "fig": null, "points": null}, {"i": 9, "sec": "第二节 跨膜运输", "title": "水通道的发现 (p55-56)", "notes": "2003年诺贝尔化学奖——'For the discovery of water channels'(水通道)。实验：将AQP1的mRNA注入非洲爪蟾卵母细胞，在低渗溶液中卵母细胞迅速膨胀并于5分钟内破裂——证明AQP1是水通道。", "page": 55, "level": "掌握", "img": "assets/img/ch02/p055.jpg", "anim": "water_channel", "fig": null, "points": null}, {"i": 10, "sec": "第二节 跨膜运输", "title": "水跨膜运动 (p57)", "notes": "Water movement across biological membranes occurs through both：①脂双层(简单扩散，较慢)；②水通道蛋白(aquaporin，快速)。水通道大大加速水的跨膜运输。", "page": 57, "level": "理解", "img": "assets/img/ch02/p057.jpg", "anim": null, "fig": "水跨膜运动有两条途径：①简单扩散通过脂双层；②经水通道蛋白(AQP)快速通过。图对比两种方式，水通道大大提高了水的通透效率。", "points": null}, {"i": 11, "sec": "第二节 跨膜运输", "title": "水通道四聚体结构 (p58)", "notes": "水通道蛋白(aquaporin)四聚体结构模型：由4个相同亚基组成，每个亚基含6个跨膜α螺旋，中央形成水通道。", "page": 58, "level": "理解", "img": "assets/img/ch02/p058.jpg", "anim": "aquaporin_tetramer", "fig": null, "points": null}, {"i": 12, "sec": "第二节 跨膜运输", "title": "钾通道结构 (p59)", "notes": "来自细菌Streptomyces lividans的静息K+通道结构：由4个亚基组成，中央形成离子通道，含选择性滤器。Roderick MacKinnon解析。", "page": 59, "level": "掌握", "img": "assets/img/ch02/p059.jpg", "anim": null, "fig": "静息钾通道(KcsA)的结构：由四个亚基组成，中央形成选择性孔道。图显示孔道内的选择性滤器，是理解“钾通道只让 K⁺ 通过”的结构基础。", "points": null}, {"i": 13, "sec": "第二节 跨膜运输", "title": "水通道的选择性 (p60)", "notes": "水通道的严格选择性：①通道直径只有0.28nm，无法通过比水分子大的物质；②通道中心最窄处带正电荷(Arg-195, His-180)，排斥阳离子(如H3O+)，只允许水通过。", "page": 60, "level": "掌握", "img": "assets/img/ch02/p060.jpg", "anim": null, "fig": "水通道的 0.28nm 选择性：水通道孔道窄，只允许水分子单列通过，而排斥离子和质子。图显示水通道的窄孔道和水的单列流动，说明“水能过、离子不能过”。", "points": null}, {"i": 14, "sec": "第二节 跨膜运输", "title": "水通道蛋白家族 (p61)", "notes": "Aquaporins是大的蛋白家族，存在于细菌、植物、动物。在哺乳动物中分布于肾脏、红细胞等，参与水的重吸收与转运。", "page": 61, "level": "理解", "img": "assets/img/ch02/p061.jpg", "anim": null, "fig": "水通道蛋白家族(AQP)：AQP1 在红细胞/肾；AQP2 在肾集合管，受抗利尿激素调节。图给出不同 AQP 的组织分布。水通道参与水的重吸收和分泌。", "points": null}, {"i": 15, "sec": "第二节 跨膜运输", "title": "哺乳动物离子分布 (p63)", "notes": "哺乳动物细胞内 vs 细胞外液的离子分布不同：胞内高K+、低Na+；胞外高Na+、高Cl-、低K+。这种不均一分布是膜电位和兴奋性的基础。", "page": 63, "level": "掌握", "img": "assets/img/ch02/p063.jpg", "anim": null, "fig": "膜两侧离子浓度表：胞外 Na⁺、Cl⁻、Ca²⁺ 高；胞内 K⁺ 高、Na⁺ 低。图用浓度对比说明离子梯度的方向，是理解静息电位和主动运输的基础。", "points": null}, {"i": 16, "sec": "第二节 跨膜运输", "title": "主动运输与离子泵 (p64)", "notes": "2)主动运输——需要能量(ATP/光能、离子梯度等)，逆浓度梯度。①离子泵：动物细胞的Na+/K+泵(Na+/K+-ATPase)，Ca2+泵等。", "page": 64, "level": "掌握", "img": "assets/img/ch02/p064.jpg", "anim": null, "fig": null, "points": null}, {"i": 17, "sec": "第二节 跨膜运输", "title": "主动运输的3种动力 (p65)", "notes": "3 ways of driving active transport主动运输的3种动力方式：①ATP驱动泵(如Na+/K+-ATPase)；②离子梯度驱动(协同运输)；③光能驱动(如细菌视紫红质)。", "page": 65, "level": "掌握", "img": "assets/img/ch02/p065.jpg", "anim": "active_transport_types", "fig": "主动运输的三种动力：①ATP 驱动(ATP 泵，如 Na⁺/K⁺-ATPase)；②离子梯度驱动(协同运输)；③光能驱动(细菌视紫红质)。图对比三种能量来源，强调主动运输逆浓度梯度、耗能。", "points": null}, {"i": 18, "sec": "第二节 跨膜运输", "title": "3种载体蛋白 (p66)", "notes": "3种不同的载体蛋白(transporter/carrier)：A被动运输；B/C主动运输。①同向协同运输(symport)——两种物质同方向；②反向协同运输(antiport)——两种物质反方向。", "page": 66, "level": "掌握", "img": "assets/img/ch02/p066.jpg", "anim": "carrier_types", "fig": null, "points": null}, {"i": 19, "sec": "第二节 跨膜运输", "title": "Na+/K+泵 (p67-68)", "notes": "细胞外/细胞内：每水解一个ATP将细胞内的3个Na+泵出细胞外，同时输入2个K+→维持质膜两侧的离子浓度梯度。Na+/K+-ATPase建立Na+胞内低、K+胞内高的浓度梯度。获诺贝尔奖。", "page": 67, "level": "掌握", "img": "assets/img/ch02/p067.jpg", "anim": "nak_pump", "fig": null, "points": null}, {"i": 20, "sec": "第二节 跨膜运输", "title": "Na+/K+泵结构 (p69)", "notes": "Na+/K+-ATPase模型：2个α亚基+2个β亚基。α亚基与Na+结合促进ATP水解→构象变化→将Na+泵出、K+泵入。", "page": 69, "level": "掌握", "img": "assets/img/ch02/p069.jpg", "anim": "nak_pump", "fig": null, "points": null}, {"i": 21, "sec": "第二节 跨膜运输", "title": "Na+/K+泵的作用 (p70)", "notes": "动物细胞Na+/K+泵的作用：①建立细胞膜电位(membrane potential)，特别是在神经和肌肉等可兴奋细胞中，是细胞信号传递的重要基础；②维持渗透平衡；③维持pH稳态；④为协同运输提供驱动力。", "page": 70, "level": "掌握", "img": "assets/img/ch02/p070.jpg", "anim": null, "fig": null, "points": null}, {"i": 22, "sec": "第二节 跨膜运输", "title": "神经传导速度 (p71)", "notes": "动作电位以约100m/s的速度传递，是神经信号快速传导的基础。", "page": 71, "level": "了解", "img": "assets/img/ch02/p071.jpg", "anim": null, "fig": "神经传导速度受轴突直径和髓鞘影响：轴突越粗、有髓鞘(跳跃式传导)速度越快。图对比无髓鞘与有髓鞘轴突的传导方式。", "points": null}, {"i": 23, "sec": "第二节 跨膜运输", "title": "静息电位 (p72-75)", "notes": "动物细胞静息电位主要来自：①Na+/K+泵产生的K+浓度梯度；②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因。膜电位由接近膜的一薄层(<1nm)离子产生。In resting neurons, K+ leak channels are open, but the more numerous gated channels are closed。", "page": 72, "level": "掌握", "img": "assets/img/ch02/p072.jpg", "anim": "resting_potential", "fig": null, "points": null}, {"i": 24, "sec": "第二节 跨膜运输", "title": "钾泄漏通道 (p75-76)", "notes": "How an ion channel can work? — selectivity filter。静息神经元中K+泄漏通道开放，而数量更多的门控通道关闭。K+泄漏通道使K+外流，形成静息电位。", "page": 76, "level": "掌握", "img": "assets/img/ch02/p076.jpg", "anim": null, "fig": "静息 K⁺ 通道(泄漏通道)在静息时持续开放，是形成静息电位的关键。图显示 K⁺ 经泄漏通道外流，膜内变负。", "points": null}, {"i": 25, "sec": "第二节 跨膜运输", "title": "K+通道的选择性滤器 (p77-79)", "notes": "细菌静息K+通道结构。所有K+通道蛋白都有选择性滤器。K+特异性的分子基础：去水化(dehydration)K+需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿→只有K+能通过，Na+因不能补偿去水化能量而被排斥。", "page": 78, "level": "掌握", "img": "assets/img/ch02/p078.jpg", "anim": "k_channel_selectivity", "fig": null, "points": null}, {"i": 26, "sec": "第二节 跨膜运输", "title": "动作电位 (p80-81)", "notes": "动作电位(action potential)：当细胞收到刺激信号时，膜电位发生变化——去极化或超极化，称动作电位。记录轴突膜电位随时间的变化可揭示动作电位的幅度和时程。", "page": 80, "level": "掌握", "img": "assets/img/ch02/p080.jpg", "anim": "action_potential", "fig": null, "points": null}, {"i": 27, "sec": "第二节 跨膜运输", "title": "协同运输 (p82)", "notes": "协同运输(cotransport)：一种主动运输方式，由Na+-K+泵(动物)、H+泵(植物)与载体蛋白协同作用。直接动力——膜两侧离子的电化学梯度。", "page": 82, "level": "掌握", "img": "assets/img/ch02/p082.jpg", "anim": "cotransport", "fig": null, "points": null}, {"i": 28, "sec": "第二节 跨膜运输", "title": "大坝类比 (p83)", "notes": "南非Blyde河大坝——类比离子梯度储能：大坝蓄水形成势能，可驱动做功；离子梯度同样储存势能，驱动协同运输。", "page": 83, "level": "了解", "img": "assets/img/ch02/p083.jpg", "anim": null, "fig": null, "points": null}, {"i": 29, "sec": "第二节 跨膜运输", "title": "葡萄糖-Na+同向转运 (p84)", "notes": "葡萄糖-Na+同向转运蛋白利用Na+电化学梯度驱动葡萄糖的摄入，如小肠上皮细胞吸收肠腔葡萄糖；植物细胞也利用H+梯度。", "page": 84, "level": "掌握", "img": "assets/img/ch02/p084.jpg", "anim": "sglt", "fig": "葡萄糖-Na⁺ 同向转运(SGLT)：Na⁺ 顺浓度梯度内流，同时把葡萄糖逆浓度梯度带入细胞。图显示 SGLT 的协同转运机制，属继发性主动运输。", "points": null}, {"i": 30, "sec": "第二节 跨膜运输", "title": "小肠上皮细胞吸收葡萄糖 (p85-87)", "notes": "小肠上皮细胞吸收葡萄糖示意图：①载体1(SGLT)——面向肠腔的顶端表面，由Na+驱动的葡萄糖同向主动运输，使细胞内有高浓度葡萄糖；②载体蛋白2(Glut2)——基底面，被动的协助扩散将葡萄糖运入血液。两步实现葡萄糖从肠腔到血液的逆浓度吸收。", "page": 85, "level": "掌握", "img": "assets/img/ch02/p085.jpg", "anim": "intestinal_glucose", "fig": null, "points": null}, {"i": 31, "sec": "第二节 跨膜运输", "title": "Na+/K+泵维持渗透平衡 (p88-89)", "notes": "动物细胞Na+/K+泵作用——维持渗透平衡：动物细胞将Na+泵出细胞外，胞外高浓度Na+(还有Cl-)，帮助细胞维持膜内外渗透压的平衡。Na+/K+-ATPase及其他离子泵必须持续工作；若停止，细胞会吸水膨胀破裂。", "page": 88, "level": "掌握", "img": "assets/img/ch02/p088.jpg", "anim": "nak_osmotic", "fig": "Na⁺/K⁺ 泵维持细胞的渗透平衡：泵出 Na⁺ 多于泵入 K⁺，使细胞内渗透压略低，防止细胞吸水涨破。图说明泵的“渗透调节”作用。", "points": null}, {"i": 32, "sec": "第二节 跨膜运输", "title": "调节pH稳态 (p90)", "notes": "Na+/K+泵调节细胞质基质的pH稳态：细胞内葡萄糖无氧代谢产生乳酸，有氧代谢产生CO2(溶于水形成H2CO3，解离产生H+)。Na+HCO3-/Cl-交换等机制维持胞内pH稳定。", "page": 90, "level": "掌握", "img": "assets/img/ch02/p090.jpg", "anim": null, "fig": "Na⁺/H⁺ 交换器(NHE)等转运蛋白调节细胞内 pH：把 H⁺ 泵出、Na⁺ 带入，维持胞质 pH 稳定。图显示 pH 稳态的转运机制。", "points": null}, {"i": 33, "sec": "第二节 跨膜运输", "title": "动植物细胞的比较 (p91-92)", "notes": "动物细胞和植物细胞的比较：植物细胞、细菌、真菌细胞的质膜上没有动物细胞的Na+/K+泵，取而代之的是H+泵，通过泵出H+建立质子梯度。动植物细胞载体蛋白介导物质转运的机制有异同。", "page": 91, "level": "掌握", "img": "assets/img/ch02/p091.jpg", "anim": null, "fig": "动物细胞与植物细胞的比较：植物细胞有细胞壁、大液泡、叶绿体；动物细胞有中心体等。图对比两者的细胞器组成，膜系统基本相似。", "points": null}], "mcq": [{"id": "ch02_mcq_14", "mod": "模块二：跨膜运输", "modI": 1, "q": "水通道蛋白(aquaporin)的发现对应哪年的诺贝尔化学奖？", "o": ["A. 2003年", "B. 1997年", "C. 2012年", "D. 2006年"], "a": "A", "e": "2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。", "kp": "ch02_s1_8"}, {"id": "ch02_mcq_15", "mod": "模块二：跨膜运输", "modI": 1, "q": "Na+/K+-ATPase每水解1个ATP转运的离子数是？", "o": ["A. 泵出2Na+,泵入3K+", "B. 泵出3Na+,泵入2K+", "C. 泵出3Na+,泵入3K+", "D. 泵出2Na+,泵入2K+"], "a": "B", "e": "每水解1个ATP，将3个Na+泵出细胞、2个K+泵入细胞，维持膜两侧离子梯度。", "kp": "ch02_s1_19"}, {"id": "ch02_mcq_16", "mod": "模块二：跨膜运输", "modI": 1, "q": "动物细胞静息电位产生的主要原因是？", "o": ["A. 静息时质膜对K+通透性大于Na+", "B. 静息时质膜对Na+通透性大于K+", "C. 钙泵活动", "D. 水通道开放"], "a": "A", "e": "静息电位主要来自Na+/K+泵产生的K+浓度梯度，以及静息时质膜对K+通透性大于Na+。", "kp": "ch02_s1_23"}, {"id": "ch02_mcq_17", "mod": "模块二：跨膜运输", "modI": 1, "q": "K+通道选择性的分子基础是？", "o": ["A. 通道大小", "B. 去水化能量与滤器羰基氧结合能相平衡", "C. 膜电位", "D. 通道正电荷"], "a": "B", "e": "K+去水化所需能量恰好由K+与选择性滤器羰基氧结合释放的能量补偿→只有K+能通过，Na+被排斥。", "kp": "ch02_s1_25"}, {"id": "ch02_mcq_18", "mod": "模块二：跨膜运输", "modI": 1, "q": "水通道的选择性由什么决定？", "o": ["A. 直径0.28nm+中心正电荷(Arg/His)", "B. 只有疏水作用", "C. 膜电位", "D. 通道长度"], "a": "A", "e": "水通道直径仅0.28nm，无法通过比水大的分子；通道中心最窄处带正电荷(Arg-195、His-180)排斥阳离子，只允许水通过。", "kp": "ch02_s1_13"}, {"id": "ch02_mcq_19", "mod": "模块二：跨膜运输", "modI": 1, "q": "主动运输的特点不包括？", "o": ["A. 逆浓度梯度", "B. 需要能量", "C. 需载体蛋白", "D. 顺浓度梯度不耗能"], "a": "D", "e": "主动运输逆浓度梯度、需能量(ATP/光能/离子梯度)、需载体蛋白。顺浓度梯度不耗能是被动运输。", "kp": "ch02_s1_17"}, {"id": "ch02_mcq_20", "mod": "模块二：跨膜运输", "modI": 1, "q": "小肠上皮细胞吸收葡萄糖的过程是？", "o": ["A. 简单扩散", "B. 顶端SGLT(Na+同向主动运输)+基底Glut2(协助扩散)", "C. 仅主动运输", "D. 仅胞吞"], "a": "B", "e": "顶端面SGLT利用Na+梯度主动转运葡萄糖入胞；基底面Glut2被动协助扩散入血。两步完成逆浓度吸收。", "kp": "ch02_s1_30"}, {"id": "ch02_mcq_21", "mod": "模块二：跨膜运输", "modI": 1, "q": "协同运输(symport)是指？", "o": ["A. 两种物质反向转运", "B. 两种物质同向转运", "C. 仅一种物质", "D. 需光能"], "a": "B", "e": "同向协同运输(symport)两种物质同方向；反向协同运输(antiport)方向相反。如葡萄糖-Na+同向转运。", "kp": "ch02_s1_27"}, {"id": "ch02_mcq_22", "mod": "模块二：跨膜运输", "modI": 1, "q": "植物细胞质膜上代替Na+/K+泵的离子泵是？", "o": ["A. Ca2+泵", "B. H+泵", "C. Cl-泵", "D. 水通道"], "a": "B", "e": "植物细胞、细菌、真菌质膜上没有Na+/K+泵，取而代之的是H+泵，泵出H+建立质子梯度。", "kp": "ch02_s1_21"}, {"id": "ch02_mcq_23", "mod": "模块二：跨膜运输", "modI": 1, "q": "脂筏(lipid raft)的主要组成是？", "o": ["A. 甘油磷脂为主", "B. 胆固醇、鞘磷脂富集区", "C. 仅蛋白质", "D. 仅糖脂"], "a": "B", "e": "脂筏是膜上胆固醇、鞘磷脂等富集的相对独立微区域，承载特定膜蛋白，参与信号传递。", "kp": "ch02_s1_2"}, {"id": "ch02_mcq_24", "mod": "模块二：跨膜运输", "modI": 1, "q": "膜脂形成脂双层的原因是？", "o": ["A. 两性分子在水中的自装配", "B. 共价键连接", "C. 酶催化", "D. 外力作用"], "a": "A", "e": "膜脂为两性分子(亲水头+疏水尾)，在水中自动、自我装配形成连续不破裂的脂双层。", "kp": "ch02_s1_2"}, {"id": "ch02_mcq_25", "mod": "模块二：跨膜运输", "modI": 1, "q": "脂质体(liposome)的应用不包括？", "o": ["A. 生物膜研究模型", "B. 药物靶向递送", "C. 膜蛋白研究", "D. 直接作为能量分子"], "a": "D", "e": "脂质体用于膜研究、膜蛋白研究、药物载体/靶向递送，不是能量分子。", "kp": "ch02_s1_10"}], "judge": [{"id": "ch02_judge_7", "modI": 1, "q": "通道蛋白转运物质时需要与被转运分子结合，并发生构象变化。", "a": "错", "e": "通道蛋白形成亲水通道，不需与底物结合；发生构象变化转运的是载体蛋白。", "kp": "ch02_s1_5"}, {"id": "ch02_judge_8", "modI": 1, "q": "Na+/K+-ATPase每水解1个ATP，泵出3个Na+、泵入2个K+。", "a": "对", "e": "每水解1个ATP，泵出3Na+、泵入2K+，维持膜两侧离子梯度。", "kp": "ch02_s1_19"}, {"id": "ch02_judge_9", "modI": 1, "q": "动物细胞静息电位主要来自Na+/K+泵产生的K+浓度梯度及静息时质膜对K+通透性大于Na+。", "a": "对", "e": "静息时K+泄漏通道开放，质膜对K+通透性大于Na+，K+外流形成静息电位。", "kp": "ch02_s1_23"}, {"id": "ch02_judge_10", "modI": 1, "q": "水通道蛋白(aquaporin)的发现获得2003年诺贝尔化学奖。", "a": "对", "e": "2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。", "kp": "ch02_s1_8"}], "fill": [{"id": "ch02_fill_7", "modI": 1, "q": "Na+/K+-ATPase每水解1个ATP,泵出________个Na+,泵入________个K+。", "a": "3,2", "kp": "ch02_s1_19"}, {"id": "ch02_fill_8", "modI": 1, "q": "动物细胞静息电位主要来自________产生的K+浓度梯度及静息时质膜对________通透性大于Na+。", "a": "Na+/K+泵,K+", "kp": "ch02_s1_23"}, {"id": "ch02_fill_9", "modI": 1, "q": "水通道蛋白(aquaporin)由________个相同亚基组成四聚体,其发现获________年诺贝尔化学奖。", "a": "4,2003", "kp": "ch02_s1_11"}, {"id": "ch02_fill_10", "modI": 1, "q": "小肠上皮细胞顶端面由________(SGLT)利用Na+梯度主动吸收葡萄糖,基底面由________(Glut2)协助扩散入血。", "a": "葡萄糖-Na+同向转运蛋白,葡萄糖载体2", "kp": "ch02_s1_30"}, {"id": "ch02_fill_11", "modI": 1, "q": "通道蛋白的三种门控方式是________、________和________。", "a": "膜电压门控,配体门控,应力门控", "kp": "ch02_s1_5"}], "short": [{"id": "ch02_short_4", "modI": 1, "q": "简述Na+/K+-ATPase的结构、机制及生理作用。", "a": "结构：2个α亚基+2个β亚基。α亚基具ATP酶活性、与Na+结合。\n\n机制：每水解1个ATP，将细胞内3个Na+泵出细胞外，同时输入2个K+。α亚基与Na+结合促进ATP水解→磷酸化→构象变化→Na+泵出、K+泵入。\n\n生理作用：\n①建立并维持膜两侧离子浓度梯度(胞内高K+、低Na+)；\n②建立细胞膜电位(membrane potential)，特别是神经和肌肉等可兴奋细胞，是信号传递的基础；\n③维持渗透平衡——泵出Na+，胞外高Na+、Cl-帮助维持膜内外渗透压平衡；\n④维持细胞质基质pH稳态；\n⑤为协同运输提供驱动力(如葡萄糖-Na+同向转运)。\n\n【诺贝尔奖】Na+/K+-ATPase研究获诺贝尔奖。若泵停止工作，细胞吸水膨胀破裂。", "kp": "ch02_s1_20"}, {"id": "ch02_short_5", "modI": 1, "q": "比较被动运输与主动运输,并举例说明。", "a": "被动运输 vs 主动运输：\n\n【被动运输】\n• 顺浓度梯度，不消耗能量；\n• ①简单扩散：不需载体，如O2、CO2、N2、激素等疏水小分子；\n• ②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT进入细胞、离子经通道蛋白；\n• 通道蛋白只参与被动运输，转运速率最快(电压/配体/应力门控)。\n\n【主动运输】\n• 逆浓度梯度，需消耗能量(ATP/光能/离子梯度)，需载体蛋白；\n• 三种动力方式：ATP驱动泵(Na+/K+-ATPase、Ca2+泵)、离子梯度驱动(协同运输)、光能驱动；\n• 同向协同运输(symport)如葡萄糖-Na+同向转运；反向协同运输(antiport)。\n\n【例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运(继发性主动运输)，基底Glut2协助扩散入血。\n\n【比较】被动运输不需能量、顺梯度；主动运输需能量、逆梯度。", "kp": "ch02_s1_16"}, {"id": "ch02_short_6", "modI": 1, "q": "简述静息电位的产生机制及K+通道的选择性原理。", "a": "【静息电位的产生】\n①Na+/K+泵产生K+浓度梯度(胞内高K+)；\n②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因；\n③K+经K+泄漏通道外流，使膜外带正电、膜内带负电，形成膜电位；\n④膜电位由接近膜的一薄层(<1nm)离子产生。\n静息神经元中K+泄漏通道开放，而数量更多的门控通道关闭。\n\n【K+通道的选择性原理】\n①所有K+通道都有选择性滤器；\n②K+去水化(dehydration)需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿；\n③Na+离子半径小、去水化能量高，不能与滤器结合补偿，故被排斥；\n④结果：K+通道只允许K+通过。\n\n【动作电位】细胞受刺激时膜电位去极化或超极化，形成动作电位，是神经信号传导的基础。", "kp": "ch02_s1_25"}], "calc": [{"id": "ch02_calc_2", "modI": 1, "q": "论述跨膜运输的主要方式及其机制。", "a": "跨膜运输分为被动运输和主动运输两大类,机制各异", "steps": "【被动运输】(顺浓度梯度，不耗能)\n①简单扩散：疏水小分子(O2/CO2/激素)直接穿过脂双层；\n②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT、水经AQP、离子经通道。\n• 通道蛋白：形成亲水通道，不与底物结合，速率最快，电压/配体/应力门控；\n• 载体蛋白：构象变化转运，如GLUT1、ADP/ATP载体。\n\n【主动运输】(逆浓度梯度，耗能，需载体)\n①ATP驱动泵：Na+/K+-ATPase(3Na+出/2K+入)、Ca2+泵、H+泵(植物)；\n②离子梯度驱动(协同运输)：同向(symport,如葡萄糖-Na+)、反向(antiport)；\n③光能驱动：细菌视紫红质。\n\n【实例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运；基底Glut2协助扩散。\n\n【意义】\n①被动运输实现顺梯度的快速交换；\n②主动运输维持离子梯度、膜电位、渗透平衡、pH稳态，是细胞生存的基础。", "kp": "ch02_s1_1"}], "term": [{"id": "ch02_term_10", "modI": 1, "term": "被动运输(Passive Transport)", "def": "①顺浓度梯度、不消耗能量的跨膜运输（定义）。②类型：简单扩散(不需载体，如O2/CO2)、协助扩散(需载体/通道蛋白，如葡萄糖经GLUT)（类型）。③特点：顺浓度梯度、不耗能（特点）。", "kps": "踩分点:①定义(1分)②类型(2分)③特点(1分)", "kp": "ch02_s1_1"}, {"id": "ch02_term_11", "modI": 1, "term": "主动运输(Active Transport)", "def": "①逆浓度梯度、需消耗能量、需载体蛋白的跨膜运输（定义）。②三种动力：ATP驱动泵、离子梯度驱动(协同运输)、光能驱动（动力）。③举例：Na+/K+-ATPase、Ca2+泵、葡萄糖-Na+同向转运（举例）。④意义：维持离子梯度、膜电位、渗透平衡、pH稳态（意义）。", "kps": "踩分点:①定义(1分)②三种动力(1分)③举例(1分)④意义(1分)", "kp": "ch02_s1_17"}, {"id": "ch02_term_12", "modI": 1, "term": "Na+/K+-ATPase(Na+/K+泵)", "def": "①动物细胞质膜上逆浓度梯度泵出Na+、泵入K+的离子泵（定义）。②结构：2α+2β亚基（结构）。③机制：每水解1个ATP，泵出3Na+、泵入2K+（机制）。④作用：建立膜电位、维持渗透平衡和pH稳态、为协同运输供能（作用）。", "kps": "踩分点:①定义(1分)②结构(1分)③机制(1分)④作用(1分)", "kp": "ch02_s1_20"}, {"id": "ch02_term_13", "modI": 1, "term": "水通道蛋白(Aquaporin)", "def": "①介导水快速跨膜运输的通道蛋白（定义）。②结构：4个相同亚基组成四聚体，每亚基6个跨膜α螺旋（结构）。③选择性：通道直径0.28nm，中心带正电荷(Arg/His)排斥阳离子（选择性）。④意义：发现获2003年诺贝尔化学奖(Peter Agre)（意义）。", "kps": "踩分点:①定义(1分)②结构(1分)③选择性(1分)④诺贝尔奖(1分)", "kp": "ch02_s1_14"}, {"id": "ch02_term_14", "modI": 1, "term": "协同运输(Cotransport)", "def": "①由离子泵建立的离子梯度驱动、经载体蛋白逆浓度转运物质的主动运输（定义）。②类型：同向协同运输(symport，如葡萄糖-Na+)、反向协同运输(antiport)（类型）。③动力：膜两侧离子的电化学梯度（动力）。④举例：小肠上皮细胞顶端SGLT吸收葡萄糖（举例）。", "kps": "踩分点:①定义(1分)②类型(1分)③动力(1分)④举例(1分)", "kp": "ch02_s1_27"}, {"id": "ch02_term_15", "modI": 1, "term": "膜电位(Membrane Potential)", "def": "①细胞膜两侧的电位差，由膜两侧离子分布不均产生（定义）。②产生：Na+/K+泵建立K+浓度梯度，静息时质膜对K+通透性大于Na+→K+外流（机制）。③意义：可兴奋细胞(神经/肌肉)信号传递的基础；动作电位是膜电位去极化/超极化的结果（意义）。", "kps": "踩分点:①定义(1分)②产生机制(2分)③意义(1分)", "kp": "ch02_s1_21"}]}], "mcq": [{"id": "ch02_mcq_1", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "生物膜流动镶嵌模型的提出者和年份是？", "o": ["A. Singer & Nicolson,1972", "B. Watson & Crick,1953", "C. Robertson,1964", "D. Singer,1988"], "a": "A", "e": "1972年Singer和Nicolson提出流动镶嵌模型：磷脂双分子层为基本骨架，蛋白质镶嵌其中，膜具流动性。", "kp": "ch02_s0_2"}, {"id": "ch02_mcq_2", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "占整个膜脂50%以上的膜脂是？", "o": ["A. 胆固醇", "B. 甘油磷脂", "C. 鞘脂", "D. 糖脂"], "a": "B", "e": "甘油磷脂为膜脂基本成分，占整个膜脂50%以上。包括磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇。", "kp": "ch02_s0_7"}, {"id": "ch02_mcq_3", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "关于胆固醇在膜中的作用,错误的是？", "o": ["A. 自身不能形成脂双层", "B. 调节膜的流动性", "C. 是脂筏基本结构成分", "D. 是膜脂含量最高的成分"], "a": "D", "e": "胆固醇自身不能形成脂双层，只能插入磷脂之间；调节流动性、增加稳定性；是脂筏成分。含量最高的膜脂是甘油磷脂。", "kp": "ch02_s0_36"}, {"id": "ch02_mcq_4", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "膜脂运动的基本方式是？", "o": ["A. 翻转运动", "B. 侧向运动", "C. 尾部摆动", "D. 自旋"], "a": "B", "e": "同一侧的侧向运动是膜脂运动的基本方式。翻转运动(flip-flop)较慢，需酶协助。", "kp": "ch02_s0_12"}, {"id": "ch02_mcq_5", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "膜脂和膜蛋白在膜上的分布特点是？", "o": ["A. 完全对称", "B. 不对称分布", "C. 随机分布", "D. 只在胞外侧"], "a": "B", "e": "膜脂和膜蛋白在生物膜上均呈不对称分布；糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。", "kp": "ch02_s0_11"}, {"id": "ch02_mcq_6", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "膜内在蛋白(integral protein)的跨膜方式是？", "o": ["A. 仅α-螺旋", "B. α-螺旋或β-折叠", "C. 仅β-折叠", "D. 无规则"], "a": "B", "e": "内在跨膜整合蛋白以α-螺旋或β-折叠方式跨膜；细菌外膜孔蛋白以β-折叠跨膜。", "kp": "ch02_s0_21"}, {"id": "ch02_mcq_7", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "人红细胞膜骨架蛋白中的血影蛋白属于？", "o": ["A. 内在蛋白", "B. 外周蛋白", "C. 脂锚定蛋白", "D. 通道蛋白"], "a": "B", "e": "血影蛋白、肌动蛋白以非共价键结合在膜内侧，属于外周膜蛋白，构成膜骨架。", "kp": "ch02_s0_23"}, {"id": "ch02_mcq_8", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "需要用特定酶才能从膜上释放的膜蛋白是？", "o": ["A. 外周蛋白", "B. 脂锚定蛋白", "C. 内在蛋白", "D. 跨膜蛋白"], "a": "B", "e": "脂锚定蛋白与膜脂共价连接，改变pH或离子强度不能去除，需特定酶(如磷脂酶)才能释放。", "kp": "ch02_s0_24"}, {"id": "ch02_mcq_9", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "影响膜流动性最主要的因素是？", "o": ["A. pH", "B. 温度", "C. 离子强度", "D. 膜蛋白种类"], "a": "B", "e": "温度是影响膜流动性最主要的因素。温度降低到相变温度时膜脂由液晶态转变为凝胶态。", "kp": "ch02_s0_30"}, {"id": "ch02_mcq_10", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "下列关于膜流动性的说法正确的是？", "o": ["A. 脂肪酸链越长流动性越高", "B. 不饱和脂肪酸越多流动性越高", "C. 胆固醇总是增加流动性", "D. 饱和脂肪酸越多流动性越高"], "a": "B", "e": "短链脂肪酸、不饱和脂肪酸(双键多)使流动性高；长链、饱和脂肪酸降低流动性；胆固醇双向调节。", "kp": "ch02_s0_30"}, {"id": "ch02_mcq_11", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "研究膜分子扩散速率的经典技术是？", "o": ["A. FRAP", "B. PCR", "C. SDS-PAGE", "D. 电镜"], "a": "A", "e": "荧光漂白恢复技术(FRAP)：标记→激光漂白→观察荧光恢复→测定扩散速率。", "kp": "ch02_s0_29"}, {"id": "ch02_mcq_12", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "人工脂双层对下列哪种物质通透性最低？", "o": ["A. O2", "B. H2O", "C. 葡萄糖", "D. Na+等离子"], "a": "D", "e": "离子几乎不能通过人工脂双层，需通道/载体蛋白。通透性：疏水分子>小极性分子>大极性分子>离子。", "kp": "ch02_s0_15"}, {"id": "ch02_mcq_13", "mod": "模块一：生物膜结构模型与组成", "modI": 0, "q": "通道蛋白的特点是？", "o": ["A. 需与运输分子结合", "B. 只参与被动运输,转运速率最快", "C. 逆浓度梯度运输", "D. 需消耗ATP"], "a": "B", "e": "通道蛋白形成亲水通道，不需与底物结合，只参与被动运输，转运速率最快；有电压/配体/应力三种门控。", "kp": "ch02_s0_25"}, {"id": "ch02_mcq_14", "mod": "模块二：跨膜运输", "modI": 1, "q": "水通道蛋白(aquaporin)的发现对应哪年的诺贝尔化学奖？", "o": ["A. 2003年", "B. 1997年", "C. 2012年", "D. 2006年"], "a": "A", "e": "2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。", "kp": "ch02_s1_8"}, {"id": "ch02_mcq_15", "mod": "模块二：跨膜运输", "modI": 1, "q": "Na+/K+-ATPase每水解1个ATP转运的离子数是？", "o": ["A. 泵出2Na+,泵入3K+", "B. 泵出3Na+,泵入2K+", "C. 泵出3Na+,泵入3K+", "D. 泵出2Na+,泵入2K+"], "a": "B", "e": "每水解1个ATP，将3个Na+泵出细胞、2个K+泵入细胞，维持膜两侧离子梯度。", "kp": "ch02_s1_19"}, {"id": "ch02_mcq_16", "mod": "模块二：跨膜运输", "modI": 1, "q": "动物细胞静息电位产生的主要原因是？", "o": ["A. 静息时质膜对K+通透性大于Na+", "B. 静息时质膜对Na+通透性大于K+", "C. 钙泵活动", "D. 水通道开放"], "a": "A", "e": "静息电位主要来自Na+/K+泵产生的K+浓度梯度，以及静息时质膜对K+通透性大于Na+。", "kp": "ch02_s1_23"}, {"id": "ch02_mcq_17", "mod": "模块二：跨膜运输", "modI": 1, "q": "K+通道选择性的分子基础是？", "o": ["A. 通道大小", "B. 去水化能量与滤器羰基氧结合能相平衡", "C. 膜电位", "D. 通道正电荷"], "a": "B", "e": "K+去水化所需能量恰好由K+与选择性滤器羰基氧结合释放的能量补偿→只有K+能通过，Na+被排斥。", "kp": "ch02_s1_25"}, {"id": "ch02_mcq_18", "mod": "模块二：跨膜运输", "modI": 1, "q": "水通道的选择性由什么决定？", "o": ["A. 直径0.28nm+中心正电荷(Arg/His)", "B. 只有疏水作用", "C. 膜电位", "D. 通道长度"], "a": "A", "e": "水通道直径仅0.28nm，无法通过比水大的分子；通道中心最窄处带正电荷(Arg-195、His-180)排斥阳离子，只允许水通过。", "kp": "ch02_s1_13"}, {"id": "ch02_mcq_19", "mod": "模块二：跨膜运输", "modI": 1, "q": "主动运输的特点不包括？", "o": ["A. 逆浓度梯度", "B. 需要能量", "C. 需载体蛋白", "D. 顺浓度梯度不耗能"], "a": "D", "e": "主动运输逆浓度梯度、需能量(ATP/光能/离子梯度)、需载体蛋白。顺浓度梯度不耗能是被动运输。", "kp": "ch02_s1_17"}, {"id": "ch02_mcq_20", "mod": "模块二：跨膜运输", "modI": 1, "q": "小肠上皮细胞吸收葡萄糖的过程是？", "o": ["A. 简单扩散", "B. 顶端SGLT(Na+同向主动运输)+基底Glut2(协助扩散)", "C. 仅主动运输", "D. 仅胞吞"], "a": "B", "e": "顶端面SGLT利用Na+梯度主动转运葡萄糖入胞；基底面Glut2被动协助扩散入血。两步完成逆浓度吸收。", "kp": "ch02_s1_30"}, {"id": "ch02_mcq_21", "mod": "模块二：跨膜运输", "modI": 1, "q": "协同运输(symport)是指？", "o": ["A. 两种物质反向转运", "B. 两种物质同向转运", "C. 仅一种物质", "D. 需光能"], "a": "B", "e": "同向协同运输(symport)两种物质同方向；反向协同运输(antiport)方向相反。如葡萄糖-Na+同向转运。", "kp": "ch02_s1_27"}, {"id": "ch02_mcq_22", "mod": "模块二：跨膜运输", "modI": 1, "q": "植物细胞质膜上代替Na+/K+泵的离子泵是？", "o": ["A. Ca2+泵", "B. H+泵", "C. Cl-泵", "D. 水通道"], "a": "B", "e": "植物细胞、细菌、真菌质膜上没有Na+/K+泵，取而代之的是H+泵，泵出H+建立质子梯度。", "kp": "ch02_s1_21"}, {"id": "ch02_mcq_23", "mod": "模块二：跨膜运输", "modI": 1, "q": "脂筏(lipid raft)的主要组成是？", "o": ["A. 甘油磷脂为主", "B. 胆固醇、鞘磷脂富集区", "C. 仅蛋白质", "D. 仅糖脂"], "a": "B", "e": "脂筏是膜上胆固醇、鞘磷脂等富集的相对独立微区域，承载特定膜蛋白，参与信号传递。", "kp": "ch02_s1_2"}, {"id": "ch02_mcq_24", "mod": "模块二：跨膜运输", "modI": 1, "q": "膜脂形成脂双层的原因是？", "o": ["A. 两性分子在水中的自装配", "B. 共价键连接", "C. 酶催化", "D. 外力作用"], "a": "A", "e": "膜脂为两性分子(亲水头+疏水尾)，在水中自动、自我装配形成连续不破裂的脂双层。", "kp": "ch02_s1_2"}, {"id": "ch02_mcq_25", "mod": "模块二：跨膜运输", "modI": 1, "q": "脂质体(liposome)的应用不包括？", "o": ["A. 生物膜研究模型", "B. 药物靶向递送", "C. 膜蛋白研究", "D. 直接作为能量分子"], "a": "D", "e": "脂质体用于膜研究、膜蛋白研究、药物载体/靶向递送，不是能量分子。", "kp": "ch02_s1_10"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "流动镶嵌模型由Singer和Nicolson于1972年提出。", "a": "对", "e": "1972年Singer和Nicolson提出流动镶嵌模型，是膜结构研究的里程碑。", "kp": "ch02_s0_2"}, {"id": "ch02_judge_2", "modI": 0, "q": "甘油磷脂是膜脂中含量最高的成分，占膜脂50%以上。", "a": "对", "e": "甘油磷脂为膜脂基本成分，占整个膜脂50%以上。", "kp": "ch02_s0_7"}, {"id": "ch02_judge_3", "modI": 0, "q": "胆固醇自身能形成脂双层，是构成膜骨架的主要成分。", "a": "错", "e": "胆固醇自身不能形成脂双层，只能插入磷脂分子之间，起调节流动性等作用。", "kp": "ch02_s0_9"}, {"id": "ch02_judge_4", "modI": 0, "q": "膜脂和膜蛋白在膜上呈不对称分布，糖脂的糖基位于细胞外侧。", "a": "对", "e": "膜脂、膜蛋白均呈不对称分布；糖蛋白和糖脂的糖基位于质膜外侧(非胞质面)。", "kp": "ch02_s0_11"}, {"id": "ch02_judge_5", "modI": 0, "q": "温度降低到相变温度以下时，膜脂由液晶态转变为凝胶态，流动性降低。", "a": "对", "e": "温度是影响膜流动性最主要的因素；降至相变温度以下膜脂由液晶态变凝胶态。", "kp": "ch02_s0_30"}, {"id": "ch02_judge_6", "modI": 0, "q": "不饱和脂肪酸含量越高，膜流动性越低。", "a": "错", "e": "不饱和脂肪酸含双键、分子弯曲、排列疏松，含量越高流动性越高。", "kp": "ch02_s0_34"}, {"id": "ch02_judge_7", "modI": 1, "q": "通道蛋白转运物质时需要与被转运分子结合，并发生构象变化。", "a": "错", "e": "通道蛋白形成亲水通道，不需与底物结合；发生构象变化转运的是载体蛋白。", "kp": "ch02_s1_5"}, {"id": "ch02_judge_8", "modI": 1, "q": "Na+/K+-ATPase每水解1个ATP，泵出3个Na+、泵入2个K+。", "a": "对", "e": "每水解1个ATP，泵出3Na+、泵入2K+，维持膜两侧离子梯度。", "kp": "ch02_s1_19"}, {"id": "ch02_judge_9", "modI": 1, "q": "动物细胞静息电位主要来自Na+/K+泵产生的K+浓度梯度及静息时质膜对K+通透性大于Na+。", "a": "对", "e": "静息时K+泄漏通道开放，质膜对K+通透性大于Na+，K+外流形成静息电位。", "kp": "ch02_s1_23"}, {"id": "ch02_judge_10", "modI": 1, "q": "水通道蛋白(aquaporin)的发现获得2003年诺贝尔化学奖。", "a": "对", "e": "2003年诺贝尔化学奖授予Peter Agre(水通道)和Roderick MacKinnon(钾通道)。", "kp": "ch02_s1_8"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "生物膜流动镶嵌模型由________和________于________年提出。", "a": "Singer,Nicolson,1972", "kp": "ch02_s0_2"}, {"id": "ch02_fill_2", "modI": 0, "q": "膜脂三大类是________、________和________,都是________分子。", "a": "甘油磷脂,鞘脂,胆固醇,两性", "kp": "ch02_s0_6"}, {"id": "ch02_fill_3", "modI": 0, "q": "占膜脂50%以上的是________；不能自身形成脂双层、只能插入磷脂之间的是________。", "a": "甘油磷脂,胆固醇", "kp": "ch02_s0_15"}, {"id": "ch02_fill_4", "modI": 0, "q": "膜脂运动的基本方式是________；双层分子间的________运动较慢。", "a": "侧向运动,翻转(flip-flop)", "kp": "ch02_s0_12"}, {"id": "ch02_fill_5", "modI": 0, "q": "膜内在蛋白以________或________方式跨膜；外周蛋白以________键结合在膜上。", "a": "α-螺旋,β-折叠,非共价", "kp": "ch02_s0_21"}, {"id": "ch02_fill_6", "modI": 0, "q": "影响膜流动性最主要的因素是________；不饱和脂肪酸越多,流动性越________。", "a": "温度,高", "kp": "ch02_s0_30"}, {"id": "ch02_fill_7", "modI": 1, "q": "Na+/K+-ATPase每水解1个ATP,泵出________个Na+,泵入________个K+。", "a": "3,2", "kp": "ch02_s1_19"}, {"id": "ch02_fill_8", "modI": 1, "q": "动物细胞静息电位主要来自________产生的K+浓度梯度及静息时质膜对________通透性大于Na+。", "a": "Na+/K+泵,K+", "kp": "ch02_s1_23"}, {"id": "ch02_fill_9", "modI": 1, "q": "水通道蛋白(aquaporin)由________个相同亚基组成四聚体,其发现获________年诺贝尔化学奖。", "a": "4,2003", "kp": "ch02_s1_11"}, {"id": "ch02_fill_10", "modI": 1, "q": "小肠上皮细胞顶端面由________(SGLT)利用Na+梯度主动吸收葡萄糖,基底面由________(Glut2)协助扩散入血。", "a": "葡萄糖-Na+同向转运蛋白,葡萄糖载体2", "kp": "ch02_s1_30"}, {"id": "ch02_fill_11", "modI": 1, "q": "通道蛋白的三种门控方式是________、________和________。", "a": "膜电压门控,配体门控,应力门控", "kp": "ch02_s1_5"}, {"id": "ch02_fill_12", "modI": 0, "q": "脂筏是膜上________、________等富集的微区域,1988年提出________模型。", "a": "胆固醇,鞘磷脂,脂筏(Lipid raft)", "kp": "ch02_s0_4"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述生物膜流动镶嵌模型的主要内容。", "a": "流动镶嵌模型(1972, Singer & Nicolson)主要内容：\n\n①磷脂双分子层是生物膜的基本结构组分——磷脂具有极性头部(亲水)和非极性尾部(疏水)，在水溶液中自动装配成脂双层；\n②膜蛋白以不同方式镶嵌于脂双层：内在蛋白(跨膜)、外周蛋白(非共价结合)、脂锚定蛋白(共价连接)；\n③膜脂和膜蛋白具有流动性——膜脂可侧向运动、翻转、摆动、自旋；膜蛋白可侧向扩散；\n④膜脂和膜蛋白分布具有不对称性——糖脂/糖蛋白的糖基位于质膜外侧；\n⑤脂类与蛋白质的流动性和不对称性是它们相互作用及与其他生物大分子相互作用的基础；\n⑥这种相互作用又一定程度上限制了膜蛋白和膜脂的流动性。\n\n【发展】此后提出脂筏模型(1988)：膜上胆固醇、鞘磷脂富集形成相对独立的微区域。\n【意义】解释了膜的许多性质：物质运输、信号转导、细胞融合等。", "kp": "ch02_s0_2"}, {"id": "ch02_short_2", "modI": 0, "q": "简述膜脂的种类、特性及其对膜流动性的影响。", "a": "膜脂分三大类：\n①甘油磷脂(占膜脂50%以上)：磷脂酰胆碱、磷脂酰丝氨酸、磷脂酰乙醇胺、磷脂酰肌醇；\n②鞘脂：鞘氨醇衍生物，分鞘磷脂、鞘糖脂，主要在高尔基体合成；\n③胆固醇：4环碳氢化合物，自身不能形成脂双层，插入磷脂之间。\n都是两性分子(亲水头+疏水尾)。\n\n膜脂特性：\n①不对称性——磷脂、糖脂分布完全不对称，糖脂位于胞外侧，胆固醇均等分布；\n②流动性——侧向运动(基本)、翻转、尾部摆动、自旋。\n\n影响膜流动性的因素：\n①温度(最主要)——温度高流动性大，降至相变温度以下变凝胶态；\n②脂肪酸链长度——短链流动性高；\n③不饱和程度——不饱和度高(双键多)流动性高；\n④胆固醇——双向调节(相变温度以上降低流动性、以下防止凝固)。", "kp": "ch02_s0_32"}, {"id": "ch02_short_3", "modI": 0, "q": "简述膜蛋白的类型及分离方法。", "a": "膜蛋白类型(按与膜结合方式)：\n\n①膜内在蛋白/跨膜蛋白(intrinsic/integral)：以α-螺旋或β-折叠跨膜，如跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白。\n②外周膜蛋白(peripheral)：以非共价键结合在膜脂极性头部或内在蛋白上，如红细胞膜骨架的血影蛋白、肌动蛋白。\n③脂锚定蛋白：与膜脂特定脂类共价连接，虽位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放，如小G蛋白。\n\n分离方法：\n①外周蛋白——高盐、改变pH或离子强度可洗脱；\n②内在蛋白——需去垢剂(离子型如SDS，非离子型如Triton X-100)溶解；\n③脂锚定蛋白——需特定酶释放。\n\n去垢剂：离子型(SDS)破坏非共价键、可能变性；非离子型(Triton X-100)温和、保持活性。", "kp": "ch02_s0_25"}, {"id": "ch02_short_4", "modI": 1, "q": "简述Na+/K+-ATPase的结构、机制及生理作用。", "a": "结构：2个α亚基+2个β亚基。α亚基具ATP酶活性、与Na+结合。\n\n机制：每水解1个ATP，将细胞内3个Na+泵出细胞外，同时输入2个K+。α亚基与Na+结合促进ATP水解→磷酸化→构象变化→Na+泵出、K+泵入。\n\n生理作用：\n①建立并维持膜两侧离子浓度梯度(胞内高K+、低Na+)；\n②建立细胞膜电位(membrane potential)，特别是神经和肌肉等可兴奋细胞，是信号传递的基础；\n③维持渗透平衡——泵出Na+，胞外高Na+、Cl-帮助维持膜内外渗透压平衡；\n④维持细胞质基质pH稳态；\n⑤为协同运输提供驱动力(如葡萄糖-Na+同向转运)。\n\n【诺贝尔奖】Na+/K+-ATPase研究获诺贝尔奖。若泵停止工作，细胞吸水膨胀破裂。", "kp": "ch02_s1_20"}, {"id": "ch02_short_5", "modI": 1, "q": "比较被动运输与主动运输,并举例说明。", "a": "被动运输 vs 主动运输：\n\n【被动运输】\n• 顺浓度梯度，不消耗能量；\n• ①简单扩散：不需载体，如O2、CO2、N2、激素等疏水小分子；\n• ②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT进入细胞、离子经通道蛋白；\n• 通道蛋白只参与被动运输，转运速率最快(电压/配体/应力门控)。\n\n【主动运输】\n• 逆浓度梯度，需消耗能量(ATP/光能/离子梯度)，需载体蛋白；\n• 三种动力方式：ATP驱动泵(Na+/K+-ATPase、Ca2+泵)、离子梯度驱动(协同运输)、光能驱动；\n• 同向协同运输(symport)如葡萄糖-Na+同向转运；反向协同运输(antiport)。\n\n【例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运(继发性主动运输)，基底Glut2协助扩散入血。\n\n【比较】被动运输不需能量、顺梯度；主动运输需能量、逆梯度。", "kp": "ch02_s1_16"}, {"id": "ch02_short_6", "modI": 1, "q": "简述静息电位的产生机制及K+通道的选择性原理。", "a": "【静息电位的产生】\n①Na+/K+泵产生K+浓度梯度(胞内高K+)；\n②动物细胞质膜在静息状态下对K+的通透性大于Na+——这是产生静息电位的主要原因；\n③K+经K+泄漏通道外流，使膜外带正电、膜内带负电，形成膜电位；\n④膜电位由接近膜的一薄层(<1nm)离子产生。\n静息神经元中K+泄漏通道开放，而数量更多的门控通道关闭。\n\n【K+通道的选择性原理】\n①所有K+通道都有选择性滤器；\n②K+去水化(dehydration)需要能量，这一能量恰好由K+与滤器羰基氧的结合所补偿；\n③Na+离子半径小、去水化能量高，不能与滤器结合补偿，故被排斥；\n④结果：K+通道只允许K+通过。\n\n【动作电位】细胞受刺激时膜电位去极化或超极化，形成动作电位，是神经信号传导的基础。", "kp": "ch02_s1_25"}], "calc": [{"id": "ch02_calc_1", "modI": 0, "q": "论述生物膜的不对称性及其生物学意义。", "a": "膜脂和膜蛋白的不对称分布是生物膜的基本特征,具有重要功能意义", "steps": "【不对称性的表现】\n①膜脂：磷脂、糖脂分布完全不对称——糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布在两侧；同一种膜脂两侧比例不同。\n②膜蛋白：分布不对称——如肠上皮细胞顶端面与基底面的转运蛋白不同(protein A、B)。\n③糖类：糖蛋白和糖脂的糖基均位于质膜外侧(非胞质面)。\n\n【生物学意义】\n①决定细胞极性——上皮细胞顶端与基底面功能不同(吸收vs转运)；\n②细胞识别与免疫——糖基位于外侧，血型抗原(A/B/AB/O)由膜糖脂/糖蛋白决定；\n③信号转导——受体、G蛋白等不对称分布，保证信号方向性；\n④物质运输——载体/通道蛋白定向分布，实现跨细胞转运(如小肠吸收葡萄糖)；\n⑤细胞融合、分裂、运动的基础。\n\n【结论】不对称性与流动性共同构成生物膜的两大特征，是膜功能多样性的分子基础。", "kp": "ch02_s0_11"}, {"id": "ch02_calc_2", "modI": 1, "q": "论述跨膜运输的主要方式及其机制。", "a": "跨膜运输分为被动运输和主动运输两大类,机制各异", "steps": "【被动运输】(顺浓度梯度，不耗能)\n①简单扩散：疏水小分子(O2/CO2/激素)直接穿过脂双层；\n②协助扩散：需载体/通道蛋白，如葡萄糖经GLUT、水经AQP、离子经通道。\n• 通道蛋白：形成亲水通道，不与底物结合，速率最快，电压/配体/应力门控；\n• 载体蛋白：构象变化转运，如GLUT1、ADP/ATP载体。\n\n【主动运输】(逆浓度梯度，耗能，需载体)\n①ATP驱动泵：Na+/K+-ATPase(3Na+出/2K+入)、Ca2+泵、H+泵(植物)；\n②离子梯度驱动(协同运输)：同向(symport,如葡萄糖-Na+)、反向(antiport)；\n③光能驱动：细菌视紫红质。\n\n【实例】小肠上皮细胞吸收葡萄糖：顶端SGLT利用Na+梯度主动转运；基底Glut2协助扩散。\n\n【意义】\n①被动运输实现顺梯度的快速交换；\n②主动运输维持离子梯度、膜电位、渗透平衡、pH稳态，是细胞生存的基础。", "kp": "ch02_s1_1"}, {"id": "ch02_calc_3", "modI": 0, "q": "论述膜流动性及其影响因素和生物学意义。", "a": "膜流动性是生物膜的基本特征,由多种因素调节,是生命活动的必要条件", "steps": "【流动性的表现】\n膜脂：侧向运动(基本)、翻转运动(慢)、尾部摆动、绕轴自旋；膜蛋白：侧向扩散。\n\n【影响因素】\n①温度(最主要)：温度高流动性大；降至相变温度以下，膜脂由液晶态→凝胶态；\n②脂肪酸链长度：短链含量高→流动性高；\n③不饱和程度：不饱和脂肪酸(双键多)使分子弯曲、排列疏松→流动性高；饱和脂肪酸排列紧密→流动性低；\n④胆固醇：双向调节——相变温度以上减弱脂肪酸链运动、降低流动性；以下阻止紧密排列、防止凝固；\n⑤膜蛋白与骨架的限制。\n\n【研究方法】FRAP(荧光漂白恢复)测定扩散速率。\n\n【生物学意义】\n①物质运输：膜融合、胞吞胞吐；\n②信号转导：受体聚集、脂筏动态；\n③细胞运动、分裂、融合；\n④膜蛋白功能发挥。\n\n【结论】膜流动性使细胞能进行各种生命活动，是细胞生存的必要条件。", "kp": "ch02_s0_30"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "流动镶嵌模型(Fluid Mosaic Model)", "def": "①1972年Singer和Nicolson提出的生物膜结构模型（定义）。②内容：磷脂双分子层为基本骨架；膜蛋白以不同方式镶嵌其中；膜脂和膜蛋白具流动性；分布具不对称性（内容）。③意义：解释膜的多种性质(运输、信号、融合)，是膜生物学的里程碑（意义）。", "kps": "踩分点:①提出者年份(1分)②内容(2分)③意义(1分)", "kp": "ch02_s0_2"}, {"id": "ch02_term_2", "modI": 0, "term": "脂筏(Lipid Raft)", "def": "①膜上胆固醇、鞘磷脂等富集形成的相对独立的微区域(1988提出)（定义）。②特点：异质性、高度动态、分子排列较紧密（特点）。③组成：含250多种蛋白；非离子去垢剂(如Triton X-100)可分离（组成）。④功能：参与细胞信息传递、物质运输等（功能）。", "kps": "踩分点:①定义(1分)②特点(1分)③组成(1分)④功能(1分)", "kp": "ch02_s0_4"}, {"id": "ch02_term_3", "modI": 0, "term": "膜脂的不对称性", "def": "①同一种膜脂在脂双层两侧分布比例不同、呈不对称分布的现象（定义）。②表现：磷脂、糖脂分布完全不对称，糖脂位于细胞外侧(非胞质侧)；胆固醇几乎均等分布（表现）。③意义：决定细胞极性、细胞识别(血型抗原)、信号转导方向性（意义）。", "kps": "踩分点:①定义(1分)②表现(2分)③意义(1分)", "kp": "ch02_s0_11"}, {"id": "ch02_term_4", "modI": 0, "term": "膜流动性(Membrane Fluidity)", "def": "①膜脂和膜蛋白在膜内运动的能力（定义）。②膜脂运动方式：侧向运动(基本)、翻转、尾部摆动、自旋（方式）。③影响因素：温度(最主要)、脂肪酸链长度、不饱和程度、胆固醇（因素）。④意义：是细胞进行物质运输、信号转导、融合、分裂等生命活动的必要条件（意义）。", "kps": "踩分点:①定义(1分)②运动方式(1分)③影响因素(1分)④意义(1分)", "kp": "ch02_s0_13"}, {"id": "ch02_term_5", "modI": 0, "term": "膜内在蛋白(Integral Protein)", "def": "①与膜脂疏水区紧密结合、需去垢剂才能溶解的膜蛋白（定义）。②跨膜方式：α-螺旋或β-折叠（方式）。③举例：跨膜受体、通道蛋白、载体蛋白、细菌外膜孔蛋白（举例）。④分离：需离子型/非离子型去垢剂溶解（分离）。", "kps": "踩分点:①定义(1分)②跨膜方式(1分)③举例(1分)④分离(1分)", "kp": "ch02_s0_21"}, {"id": "ch02_term_6", "modI": 0, "term": "外周膜蛋白(Peripheral Protein)", "def": "①以非共价键结合在膜脂极性头部或内在蛋白上的膜蛋白（定义）。②特点：不插入脂双层疏水区（特点）。③举例：红细胞膜骨架的血影蛋白、肌动蛋白（举例）。④分离：高盐、改变pH或离子强度可洗脱（分离）。", "kps": "踩分点:①定义(1分)②特点(1分)③举例(1分)④分离(1分)", "kp": "ch02_s0_23"}, {"id": "ch02_term_7", "modI": 0, "term": "脂锚定蛋白", "def": "①与膜脂特定脂类以共价键连接于膜上的膜蛋白（定义）。②特点：位于外周但改变pH/离子强度不能去除，需特定酶(磷脂酶)释放（特点）。③举例：小G蛋白(Ras等)（举例）。", "kps": "踩分点:①定义(1分)②特点(2分)③举例(1分)", "kp": "ch02_s0_24"}, {"id": "ch02_term_8", "modI": 0, "term": "脂质体(Liposome)", "def": "①人工把纯磷脂/磷脂酰胆碱加入水中自我装配形成的封闭球形小泡，直径25nm-1mm（定义）。②结构：脂双层包围水相（结构）。③应用：生物膜研究模型、膜蛋白研究、药物靶向递送载体（应用）。", "kps": "踩分点:①定义(1分)②结构(1分)③应用(2分)", "kp": "ch02_s0_16"}, {"id": "ch02_term_9", "modI": 0, "term": "去垢剂(Detergent)", "def": "①能溶解膜蛋白的两亲性物质（定义）。②分类：离子型(如SDS)——破坏非共价键、可能变性；非离子型(如Triton X-100)——温和、保持活性（分类）。③用途：溶解膜内在蛋白、分离纯化膜蛋白（用途）。", "kps": "踩分点:①定义(1分)②分类(2分)③用途(1分)", "kp": "ch02_s0_20"}, {"id": "ch02_term_10", "modI": 1, "term": "被动运输(Passive Transport)", "def": "①顺浓度梯度、不消耗能量的跨膜运输（定义）。②类型：简单扩散(不需载体，如O2/CO2)、协助扩散(需载体/通道蛋白，如葡萄糖经GLUT)（类型）。③特点：顺浓度梯度、不耗能（特点）。", "kps": "踩分点:①定义(1分)②类型(2分)③特点(1分)", "kp": "ch02_s1_1"}, {"id": "ch02_term_11", "modI": 1, "term": "主动运输(Active Transport)", "def": "①逆浓度梯度、需消耗能量、需载体蛋白的跨膜运输（定义）。②三种动力：ATP驱动泵、离子梯度驱动(协同运输)、光能驱动（动力）。③举例：Na+/K+-ATPase、Ca2+泵、葡萄糖-Na+同向转运（举例）。④意义：维持离子梯度、膜电位、渗透平衡、pH稳态（意义）。", "kps": "踩分点:①定义(1分)②三种动力(1分)③举例(1分)④意义(1分)", "kp": "ch02_s1_17"}, {"id": "ch02_term_12", "modI": 1, "term": "Na+/K+-ATPase(Na+/K+泵)", "def": "①动物细胞质膜上逆浓度梯度泵出Na+、泵入K+的离子泵（定义）。②结构：2α+2β亚基（结构）。③机制：每水解1个ATP，泵出3Na+、泵入2K+（机制）。④作用：建立膜电位、维持渗透平衡和pH稳态、为协同运输供能（作用）。", "kps": "踩分点:①定义(1分)②结构(1分)③机制(1分)④作用(1分)", "kp": "ch02_s1_20"}, {"id": "ch02_term_13", "modI": 1, "term": "水通道蛋白(Aquaporin)", "def": "①介导水快速跨膜运输的通道蛋白（定义）。②结构：4个相同亚基组成四聚体，每亚基6个跨膜α螺旋（结构）。③选择性：通道直径0.28nm，中心带正电荷(Arg/His)排斥阳离子（选择性）。④意义：发现获2003年诺贝尔化学奖(Peter Agre)（意义）。", "kps": "踩分点:①定义(1分)②结构(1分)③选择性(1分)④诺贝尔奖(1分)", "kp": "ch02_s1_14"}, {"id": "ch02_term_14", "modI": 1, "term": "协同运输(Cotransport)", "def": "①由离子泵建立的离子梯度驱动、经载体蛋白逆浓度转运物质的主动运输（定义）。②类型：同向协同运输(symport，如葡萄糖-Na+)、反向协同运输(antiport)（类型）。③动力：膜两侧离子的电化学梯度（动力）。④举例：小肠上皮细胞顶端SGLT吸收葡萄糖（举例）。", "kps": "踩分点:①定义(1分)②类型(1分)③动力(1分)④举例(1分)", "kp": "ch02_s1_27"}, {"id": "ch02_term_15", "modI": 1, "term": "膜电位(Membrane Potential)", "def": "①细胞膜两侧的电位差，由膜两侧离子分布不均产生（定义）。②产生：Na+/K+泵建立K+浓度梯度，静息时质膜对K+通透性大于Na+→K+外流（机制）。③意义：可兴奋细胞(神经/肌肉)信号传递的基础；动作电位是膜电位去极化/超极化的结果（意义）。", "kps": "踩分点:①定义(1分)②产生机制(2分)③意义(1分)", "kp": "ch02_s1_21"}]};